NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'II Kings'

CHAPTERS = {
    1: {
        1: 'Ahabin kuoleman jälkeen Mooab luopui Israelista.',
        2: 'Ahasja putosi Samariassa yläsalinsa ristikon läpi ja makasi sairaana. Hän lähetti sanansaattajia ja sanoi heille: "Menkää ja kysykää Baal-Sebubilta, Ekronin jumalalta, toivunko tästä taudista."',
        3: 'Mutta Herran enkeli oli sanonut tisbeläiselle Elialle: "Nouse ja mene Samarian kuninkaan sanansaattajia vastaan ja sano heille: \'Eikö ole Jumalaa Israelissa, koska menette kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta?\'',
        4: 'Sen tähden Herra sanoo näin: \'Vuoteesta, johon olet noussut, et enää astu alas, sillä sinun on kuoltava.\'" Ja Elia lähti tiehensä.',
        5: 'Kun sanansaattajat palasivat kuninkaan luo, hän kysyi heiltä: "Minkä tähden te tulette takaisin?"',
        6: 'He vastasivat hänelle: "Meitä vastaan tuli mies, joka sanoi meille: \'Menkää takaisin kuninkaan luo, joka on teidät lähettänyt, ja sanokaa hänelle: Näin sanoo Herra: Eikö ole Jumalaa Israelissa, koska sinä lähetät kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta? Sen tähden sinä et enää astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava.\'"',
        7: 'Hän kysyi heiltä: "Minkä näköinen mies oli, joka tuli teitä vastaan ja puhui teille tuollaista?"',
        8: 'He vastasivat hänelle: "Hänellä oli yllään karvanahka ja nahkavyö vyötäisillä." Silloin hän sanoi: "Se oli tisbeläinen Elia."',
        9: 'Sitten hän lähetti hänen luokseen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Kun tämä tuli hänen luokseen hänen istuessaan vuoren kukkulalla, hän sanoi hänelle: "Sinä Jumalan mies, kuningas käskee: Tule alas."',
        10: 'Mutta Elia vastasi ja sanoi viidenkymmenen päämiehelle: "Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja viisikymmentä miestäsi." Silloin tuli taivaasta tuli ja kulutti hänet ja hänen viisikymmentä miestään.',
        11: 'Hän lähetti taas hänen luokseen toisen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Tämä lausui ja sanoi hänelle: "Sinä Jumalan mies, näin käskee kuningas: Tule kiireen vilkkaa alas."',
        12: 'Mutta Elia vastasi ja sanoi heille: "Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja viisikymmentä miestäsi." Silloin tuli taivaasta Jumalan tuli ja kulutti hänet ja hänen viisikymmentä miestään.',
        13: 'Hän lähetti vielä kolmannen viidenkymmenen päämiehen ja hänen viisikymmentä miestään. Tämä kolmas viidenkymmenen päämies meni sinne, ja kun hän tuli perille, hän polvistui Elian eteen ja anoi häneltä armoa ja sanoi hänelle: "Sinä Jumalan mies, olkoon henkeni ja näiden viidenkymmenen palvelijasi henki kallis silmissäsi.',
        14: 'Katso, tuli on tullut taivaasta ja kuluttanut ne kaksi ensimmäistä viidenkymmenen päämiestä ja heidän viisikymmentä miestään, mutta olkoon henkeni kallis silmissäsi."',
        15: 'Herran enkeli sanoi Elialle: "Mene alas hänen kanssaan, älä pelkää häntä." Hän nousi ja meni hänen kanssaan kuninkaan luo.',
        16: 'Hän sanoi hänelle: "Näin sanoo Herra: Koska lähetit sanansaattajia kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta, ikään kuin Israelissa ei olisi Jumalaa, jolta voisi kysyä neuvoa, sen tähden sinä et astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava."',
        17: 'Ja hän kuoli, Herran sanan mukaan, jonka Elia oli puhunut. Jooram tuli kuninkaaksi hänen jälkeensä Jooramin, Joosafatin pojan, Juudan kuninkaan, toisena hallitusvuotena, sillä Ahasjalla ei ollut poikaa.',
        18: 'Mitä muuta on kerrottavaa Ahasjasta, siitä, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
    },
    2: {
        1: 'Silloin, kun Herra oli vievä Elian tuulispäässä taivaaseen, kulkivat Elia ja Elisa Gilgalista.',
        2: 'Elia sanoi Elisalle: "Jää tähän, sillä Herra on lähettänyt minut Beeteliin asti." Mutta Elisa vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua." Ja he menivät Beeteliin.',
        3: 'Beetelissä olevat profeetanoppilaat tulivat Elisan luo ja sanoivat hänelle: "Tiedätkö, että Herra tänä päivänä ottaa herrasi pois sinun pääsi yli?" Hän vastasi: "Tiedän kyllä, olkaa vaiti."',
        4: 'Elia sanoi hänelle: "Elisa, jää tähän, sillä Herra on lähettänyt minut Jerikoon." Mutta hän vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua." He tulivat Jerikoon.',
        5: 'Jerikossa olevat profeetanoppilaat astuivat Elisan luo ja sanoivat hänelle: "Tiedätkö, että Herra tänä päivänä ottaa herrasi pois pääsi yli?" Hän vastasi: "Minä kyllä tiedän, olkaa vaiti."',
        6: 'Elia sanoi hänelle: "Jää tähän, sillä Herra on lähettänyt minut Jordanille." Mutta hän vastasi: "Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua." He kulkivat molemmat yhdessä.',
        7: 'Mutta myös profeetanoppilaita lähti matkaan viisikymmentä miestä, ja he asettuivat syrjään jonkin matkan päähän näiden kahden pysähtyessä Jordanille.',
        8: 'Elia otti viittansa, kääri sen kokoon ja löi veteen, ja vesi jakaantui kummallekin puolelle, ja he kävivät molemmat virran yli kuivaa myöten.',
        9: 'Kun he olivat tulleet yli, Elia sanoi Elisalle: "Pyydä minua tekemään hyväksesi jotakin, ennen kuin minut otetaan pois luotasi." Elisa sanoi: "Tulkoon minuun hengestäsi kaksinkertainen osa."',
        10: 'Hän vastasi: "Pyyntösi on vaikea täyttää. Mutta jos näet, kuinka minut otetaan pois luotasi, se täytetään, jollet, se jää täyttämättä."',
        11: 'Kun he niin kulkivat ja puhelivat, katso, äkkiä ilmestyivät tuliset vaunut ja tuliset hevoset, ja ne erottivat heidät toisistaan, ja Elia nousi tuulispäässä taivaaseen.',
        12: 'Kun Elisa sen näki, hän huusi: "Isäni, isäni! Israelin sotavaunut ja ratsumiehet!" Hän ei enää nähnyt häntä. Hän tarttui vaatteisiinsa ja repäisi ne kahdeksi kappaleeksi.',
        13: 'Sitten hän otti maasta Elian viitan, joka oli pudonnut hänen päältään, palasi takaisin ja pysähtyi Jordanin rannalle.',
        14: 'Hän otti Elian viitan, joka oli pudonnut tämän päältä, löi veteen ja sanoi: "Missä on Herra, Elian Jumala?" Kun hän siis löi veteen, se jakaantui kummallekin puolelle, ja Elisa käveli virran yli.',
        15: 'Kun Jerikosta tulleet profeetanoppilaat näkivät sen edessään, he sanoivat: "Elian henki on laskeutunut Elisaan." Niin he tulivat häntä vastaan ja kumartuivat hänen edessään maahan.',
        16: 'He sanoivat hänelle: "Katso, palvelijoidesi joukossa on viisikymmentä urhoollista miestä, menkööt he etsimään isäntääsi. Ehkä Herran Henki on vienyt hänet ja heittänyt jollekin vuorelle tai johonkin laaksoon." Hän vastasi: "Älkää lähettäkö."',
        17: 'Mutta he pyysivät häntä pyytämällä kyllästyksiin asti, kunnes hän sanoi: "Lähettäkää." Niin he lähettivät viisikymmentä miestä. Nämä etsivät kolme päivää, mutta eivät löytäneet häntä.',
        18: 'Kun he tulivat takaisin hänen luokseen, hänen ollessaan Jerikossa, hän sanoi heille: "Enkö minä kieltänyt teitä menemästä?"',
        19: 'Kaupungin miehet sanoivat Elisalle: "Katso, kaupungin asema on hyvä, niin kuin herrani näkee, mutta vesi on huonoa, ja maassa syntyy keskosia."',
        20: 'Hän sanoi: "Tuokaa minulle uusi malja ja pankaa siihen suoloja." He toivat sen hänelle.',
        21: 'Hän meni vesien lähteelle ja heitti siihen suolat, sanoen: "Näin sanoo Herra: Minä olen parantanut tämän veden. Siitä ei tule enää kuolemaa eikä keskenmenoa."',
        22: 'Vesi tuli terveelliseksi aina tähän päivään asti Elisan sanan mukaan, jonka hän puhui.',
        23: 'Sieltä hän meni Beeteliin, ja hänen kävellessään tietä tuli nuoria poikia kaupungista, ja he pilkkasivat häntä ja sanoivat hänelle: "Nouse ylös, kaljupää, nouse ylös, kaljupää!"',
        24: 'Kun hän kääntyi ja näki heidät, hän kirosi heidät Herran nimeen. Silloin tuli metsästä kaksi karhua ja raateli neljäkymmentä kaksi poikaa kuoliaaksi.',
        25: 'Sieltä hän meni Karmel-vuorelle ja palasi sieltä Samariaan.',
    },
    3: {
        1: 'Jooram, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, kahdeksantenatoista hallitusvuotena, ja hän hallitsi kaksitoista vuotta.',
        2: 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niin kuin hänen isänsä ja äitinsä, sillä hän poisti Baalin patsaan, jonka hänen isänsä oli teettänyt.',
        3: 'Kuitenkin hän riippui kiinni Jerobeamin, Nebatin pojan, synnissä, jolla tämä oli saattanut Israelin tekemään syntiä. Siitä hän ei luopunut.',
        4: 'Meesa, Mooabin kuningas, omisti lammaslaumoja ja maksoi verona Israelin kuninkaalle satatuhatta karitsaa ja sadantuhannen pässin villat.',
        5: 'Mutta Ahabin kuoltua Mooabin kuningas luopui Israelin kuninkaasta.',
        6: 'Siihen aikaan kuningas Jooram lähti Samariasta ja katsasti koko Israelin.',
        7: 'Hän meni ja lähetti Joosafatille Juudan kuninkaalle sanan: "Mooabin kuningas on luopunut minusta. Lähdetkö kanssani sotaan Mooabia vastaan?" Hän vastasi: "Lähden, minä niin kuin sinä, minun kansani niin kuin sinun kansasi, minun hevoseni niin kuin sinun hevosesi!"',
        8: 'Joosafat kysyi: "Mitä tietä meidän on sinne mentävä?" Hän vastasi: "Edomin erämaan tietä."',
        9: 'Israelin kuningas, Juudan kuningas ja Edomin kuningas lähtivät liikkeelle. Mutta kun he olivat kierrellen kulkeneet seitsemän päivän matkan eikä ollut vettä sotajoukolle eikä juhdille, jotka seurasivat heitä,',
        10: 'Israelin kuningas sanoi: "Voi, Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin!"',
        11: 'Mutta Joosafat sanoi: "Eikö täällä ole ketään Herran profeettaa, kysyäksemme hänen kauttaan neuvoa Herralta?" Silloin eräs Israelin kuninkaan palvelijoista vastasi ja sanoi: "Täällä on Elisa, Saafatin poika, joka vuodatti vettä Elian käsille."',
        12: 'Joosafat sanoi: "Hänellä on Herran sana." Israelin kuningas, Joosafat ja Edomin kuningas menivät hänen luokseen.',
        13: 'Elisa sanoi Israelin kuninkaalle: "Mitä minulla on tekemistä kanssasi? Mene isäsi ja äitisi profeettojen luo." Israelin kuningas sanoi hänelle: "Ei niin! Sillä Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin."',
        14: 'Elisa sanoi: "Niin totta kuin Herra Sebaot elää, jonka edessä seison: jollen tahtoisi tehdä Joosafatille, Juudan kuninkaalle, mieliksi, tosiaankaan en katsoisi sinuun enkä huomaisi sinua.',
        15: 'Mutta tuokaa minulle nyt harpunsoittaja." Kun harpunsoittaja soitti, Herran käsi laskeutui hänen päälleen,',
        16: 'ja hän sanoi: "Näin sanoo Herra: Tehkää tämä laakso kuoppia täyteen.',
        17: 'Sillä näin sanoo Herra: Te ette tule näkemään tuulta ettekä sadetta, ja kuitenkin tämä laakso tulee vettä täyteen. Niin te saatte juoda, sekä te että karjanne ja juhtanne.',
        18: 'Mutta tämä on Herran silmissä pieni asia: hän antaa Mooabin teidän käsiinne,',
        19: 'ja te valloitatte kaikki varustetut kaupungit ja kaikki valitut kaupungit, kaadatte kaikki hedelmäpuut, tukitte kaikki vesilähteet ja turmelette kivillä kaikki hyvät peltopalstat."',
        20: 'Katso, seuraavana aamuna, sinä hetkenä, jona ruokauhri uhrataan, vettä tuli Edomista päin, niin että maa tuli vettä täyteen.',
        21: 'Kun kaikki mooabilaiset kuulivat, että kuninkaat olivat lähteneet sotaan heitä vastaan, kutsuttiin koolle kaikki miekkaan vyöttäytyvät ja myös vanhemmat miehet, ja he asettuivat rajalle.',
        22: 'Varhain aamulla, kun aurinko nousi ja paistoi veteen, näkivät mooabilaiset, että vesi heidän edessään oli punaista kuin veri.',
        23: 'He sanoivat: "Se on verta. Varmaan kuninkaat ovat joutuneet taisteluun keskenään ja surmanneet toisensa. Nyt saaliin ryöstöön, Mooab!"',
        24: 'Mutta kun he tulivat Israelin leiriin, nousivat israelilaiset ja voittivat mooabilaiset, niin että nämä pakenivat heitä. He hyökkäsivät maahan ja voittivat uudelleen mooabilaiset.',
        25: 'He hävittivät kaupungit, kaikille hyville peltopalstoille heitti kukin heistä kiven, täyttäen ne. He tukkivat kaikki vesilähteet ja kaatoivat kaikki hedelmäpuut, niin että ainoastaan Kiir-Haresetissa jäivät kivet paikoilleen. Linkomiehet piirittivät kaupungin ja ampuivat sitä.',
        26: 'Kun Mooabin kuningas näki joutuvansa tappiolle taistelussa, hän otti mukaansa seitsemänsataa miekkamiestä murtautuakseen Edomin kuninkaan luo. Mutta he eivät voineet.',
        27: 'Hän otti poikansa, esikoisensa, jonka oli määrä tulla kuninkaaksi hänen jälkeensä, ja uhrasi hänet polttouhriksi muurilla. Silloin suuri viha kohtasi Israelia, niin että he lähtivät sieltä ja palasivat omaan maahansa.',
    },
    4: {
        1: 'Eräs nainen, profeetanoppilaan vaimo, huusi Elisalle sanoen: "Mieheni, palvelijasi, kuoli, ja sinä tiedät, että palvelijasi oli herraapelkäävä mies. Nyt velkoja tulee ottamaan molemmat poikani orjikseen."',
        2: 'Elisa sanoi hänelle: "Mitä teen hyväksesi? Sano minulle, mitä sinulla on talossasi." Hän vastasi: "Palvelijattarellasi ei ole talossa muuta kuin öljyä sen verran, mitä tarvitsen voidellakseni itseäni."',
        3: 'Silloin hän sanoi: "Mene ja lainaa itsellesi astioita kylästä, kaikilta naapureiltasi, tyhjiä astioita, tarpeeksi paljon.',
        4: 'Mene sitten sisään, sulje ovi jälkeesi ja poikiesi jälkeen ja kaada kaikkiin niihin astioihin. Aina kun astia on täysi, nosta se syrjään."',
        5: 'Niin hän meni pois hänen luotaan ja sulki oven jälkeensä ja poikiensa jälkeen. Nämä toivat sitten hänelle astiat, ja hän kaatoi niihin.',
        6: 'Kun astiat olivat täynnä, hän sanoi pojalleen: "Tuo minulle vielä yksi astia." Mutta hän vastasi hänelle: "Ei ole enää astiaa." Silloin öljy tyrehtyi.',
        7: 'Hän meni ja kertoi sen Jumalan miehelle. Tämä sanoi: "Mene, myy öljy ja maksa velkasi. Sinä ja poikasi elätte siitä, mikä jää jäljelle."',
        8: 'Eräänä päivänä Elisa meni Suunemiin, ja siellä oli arvossa pidetty nainen, joka vaati häntä aterioimaan. Niin usein kuin hän kulki sen kautta, hän poikkesi sinne aterioimaan.',
        9: 'Nainen sanoi miehelleen: "Katso, minä olen huomannut, että hän, joka aina kulkee kauttamme, on pyhä Jumalan mies.',
        10: 'Muurauttakaamme pieni ullakkohuone ja pankaamme hänelle sinne vuode, pöytä, tuoli ja lamppu, niin että hän tullessaan luoksemme voi vetäytyä sinne."',
        11: 'Eräänä päivänä hän sitten tuli sinne, poikkesi ullakkohuoneeseen ja pani sinne maata.',
        12: 'Hän sanoi palvelijalleen Geehasille: "Kutsu suunemilainen nainen." Hän kutsui tämän, ja hän astui hänen eteensä.',
        13: 'Hän sanoi palvelijalle: "Sano hänelle: \'Katso, sinä olet nähnyt kaiken tämän vaivan meidän tähtemme. Voinko tehdä jotakin hyväksesi? Onko sinulla jotakin esitettävää kuninkaalle tai sotapäällikölle?\'" Mutta hän vastasi: "Minähän asun heimoni keskellä."',
        14: 'Hän kysyi: "Eikö siis voi tehdä mitään hänen hyväkseen?" Geehasi vastasi: "Voi kyllä: hänellä ei ole poikaa, ja hänen miehensä on vanha."',
        15: 'Hän sanoi: "Kutsu hänet." Niin tämä kutsui hänet, ja hän astui ovelle.',
        16: 'Elisa sanoi: "Tähän aikaan tulevana vuonna on sinulla sylissäsi poika." Hän vastasi: "Ei, herrani, sinä Jumalan mies, älä petä palvelijatartasi."',
        17: 'Mutta vaimo tuli raskaaksi ja synnytti pojan seuraavana vuonna juuri sinä aikana, jonka Elisa oli hänelle sanonut.',
        18: 'Kun poika oli kasvanut isoksi, hän meni eräänä päivänä isänsä luo, joka oli leikkuuväen luona.',
        19: 'Hän valitti isälleen: "Voi minun päätäni, voi minun päätäni!" Tämä sanoi palvelijalle: "Kanna hänet äitinsä luo."',
        20: 'Niin palvelija otti hänet ja vei hänet äitinsä luo. Poika istui hänen polvillaan puoleenpäivään asti. Sitten hän kuoli.',
        21: 'Äiti meni ylös ja laski hänet Jumalan miehen vuoteeseen, sulki oven, niin että poika jäi yksin, ja lähti pois.',
        22: 'Hän kutsui miehensä ja sanoi: "Lähetä minulle palvelija ja aasintamma, niin minä riennän Jumalan miehen luo ja tulen heti takaisin."',
        23: 'Hän sanoi: "Miksi menet hänen luokseen tänä päivänä? Eihän nyt ole uusikuu eikä sapatti." Hän vastasi: "Ole huoleti."',
        24: 'Hän satuloi aasintamman ja sanoi palvelijalleen: "Aja yhä eteenpäin äläkä keskeytä matkaani, ennen kuin sanon sinulle."',
        25: 'Hän lähti ja tuli Jumalan miehen luo Karmel-vuorelle. Kun Jumalan mies näki hänet kaukaa, hän sanoi palvelijalleen Geehasille: "Katso, se on suunemilainen nainen.',
        26: 'Riennä nyt häntä vastaan ja kysy häneltä: \'Voitko hyvin, voivatko miehesi ja poikasi hyvin?\'" Hän vastasi: "Hyvin."',
        27: 'Tultuaan vuorelle Jumalan miehen luo hän tarttui hänen jalkoihinsa. Geehasi astui esiin työntääkseen hänet pois. Mutta Jumalan mies sanoi: "Jätä hänet rauhaan, sillä hänen sielunsa on murheellinen, ja Herra on salannut sen minulta eikä ole ilmoittanut sitä minulle."',
        28: 'Hän sanoi: "Pyysinkö minä poikaa herraltani? Enkö sanonut: \'Älä uskottele minulle\'?"',
        29: 'Silloin Elisa sanoi Geehasille: "Vyötä kupeesi ja ota sauvani käteesi ja mene. Jos kohtaat jonkun, älä tervehdi häntä, ja jos joku tervehtii sinua, älä vastaa. Pane sauvani pojan kasvoille."',
        30: 'Mutta pojan äiti sanoi: "Niin totta kuin Herra elää, ja niin totta kuin sielusi elää: en jätä sinua." Elisa nousi ja seurasi häntä.',
        31: 'Mutta Geehasi oli mennyt heidän edellään ja pannut sauvan pojan kasvoille, mutta tämä ei äännähtänyt eikä kuullut. Hän tuli takaisin häntä vastaan ja kertoi hänelle sanoen: "Poika ei herännyt."',
        32: 'Kun Elisa tuli huoneeseen, katso, poika makasi hänen vuoteessaan kuolleena.',
        33: 'Tultuaan sisään hän sulki oven, niin että he jäivät kahden, ja hän rukoili Herraa.',
        34: 'Sen jälkeen hän nousi vuoteelle ja laskeutui pojan yli, pannen suunsa hänen suunsa päälle, silmänsä hänen silmiensä päälle ja kätensä hänen kättensä päälle. Kun hän näin kumartui hänen ylitseen, lämpeni pojan ruumis.',
        35: 'Sitten hän kulki huoneessa kerran edestakaisin ja nousi ja kumartui hänen ylitseen. Silloin poika aivasti seitsemän kertaa, ja sen jälkeen poika avasi silmänsä.',
        36: 'Hän kutsui Geehasin ja sanoi: "Kutsu suunemilainen nainen." Niin hän kutsui naisen, ja tämä tuli hänen luokseen. Hän sanoi: "Ota poikasi."',
        37: 'Silloin nainen tuli ja lankesi hänen jalkojensa juureen, kumartui maahan ja otti poikansa ja meni ulos.',
        38: 'Elisa palasi Gilgaliin, ja maassa oli nälänhätä. Kun profeetanoppilaat istuivat hänen edessään, hän sanoi palvelijalleen: "Pane suuri pata liedelle ja keitä keitto profeetanoppilaille."',
        39: 'Eräs heistä meni kedolle poimimaan yrttejä ja löysi villin köynnöskasvin ja poimi siitä villikurkkuja viittansa täyteen. Tultuaan hän leikkeli ne keittopataan, sillä he eivät tunteneet niitä.',
        40: 'He kaatoivat miesten syödä, mutta kun nämä maistoivat keittoa, he huusivat ja sanoivat: "Jumalan mies, padassa on kuolema!" Eivätkä he voineet syödä.',
        41: 'Silloin hän sanoi: "Tuokaa jauhoja." Sitten hän heitti ne pataan, ja sanoi: "Kaatakaa väen syödä", eikä padassa ollut mitään vahingollista.',
        42: 'Eräs mies tuli Baal-Saalisasta ja toi Jumalan miehelle ensi sadon leipää, kaksikymmentä ohraleipää ja uutta viljaa repussaan. Silloin Elisa sanoi: "Anna väelle syötävää."',
        43: 'Mutta hänen palvelijansa sanoi: "Kuinka voin tarjota siitä sadalle miehelle?" Hän sanoi: "Anna väelle syödä, sillä näin sanoo Herra: He syövät, ja jää tähteeksikin."',
        44: 'Niin hän tarjosi heille, ja he söivät, ja jäi tähteeksikin, Herran sanan mukaan.',
    },
    5: {
        1: 'Naeman, Aramin kuninkaan sotapäällikkö, oli herransa hyvin arvossa pitämä ja suurta kunnioitusta nauttiva mies, sillä hänen kauttaan Herra oli antanut Aramille voiton. Hän oli väkevä sankari, mutta spitaalinen.',
        2: 'Kerran aramilaiset olivat menneet ryöstöretkelle ja tuoneet Israelin maasta vankina pienen tytön, joka joutui palvelukseen Naemanin puolisolle.',
        3: 'Tyttö sanoi emännälleen: "Oi, jospa herrani kävisi profeetan luona Samariassa! Hän kyllä päästäisi hänet hänen spitaalistaan."',
        4: 'Naeman meni ja kertoi tämän herralleen, sanoen: "Niin ja niin on tyttö, joka on Israelin maasta, puhunut."',
        5: 'Aramin kuningas vastasi: "Mene vain sinne. Minä lähetän kirjeen Israelin kuninkaalle." Naeman lähti sinne ja otti mukaansa kymmenen talenttia hopeaa, kuusituhatta sekeliä kultaa ja kymmenen juhlapukua.',
        6: 'Hän vei Israelin kuninkaalle kirjeen, joka kuului näin: "Kun tämä kirje tulee sinulle, katso, minä olen lähettänyt luoksesi palvelijani Naemanin, että päästäisit hänet hänen spitaalistaan."',
        7: 'Kun Israelin kuningas oli lukenut kirjeen, hän repäisi vaatteensa ja sanoi: "Olenko minä Jumala, joka ottaa elämän ja antaa elämän, koska hän käskee minua päästämään miehen hänen spitaalistaan? Ymmärtäkää ja nähkää, että hän etsii aihetta minua vastaan."',
        8: 'Kun Jumalan mies Elisa kuuli, että Israelin kuningas oli reväissyt vaatteensa, hän lähetti kuninkaalle sanan: "Miksi olet reväissyt vaatteesi? Anna hänen tulla luokseni, niin hän tulee tietämään, että Israelissa on profeetta."',
        9: 'Naeman tuli hevosineen ja vaunuineen ja pysähtyi Elisan talon oven eteen.',
        10: 'Elisa lähetti hänen luokseen sanansaattajan ja käski sanoa: "Mene ja peseydy seitsemän kertaa Jordanissa, niin lihasi tulee entiselleen, ja tulet puhtaaksi."',
        11: 'Mutta Naeman vihastui ja lähti pois sanoen: "Katso, minä luulin hänen edes tulevan ja astuvan esiin ja rukoilevan Herran, Jumalansa, nimeä, heiluttavan kättään sen paikan yli ja poistavan spitaalin.',
        12: 'Eivätkö Damaskon virrat, Abana ja Parpar, ole kaikkia Israelin vesiä paremmat? Voinhan yhtä hyvin peseytyä niissä tullakseni puhtaaksi." Hän kääntyi pois ja meni tiehensä kiukustuneena.',
        13: 'Mutta hänen palvelijansa astuivat esiin ja puhuttelivat häntä ja sanoivat: "Isäni, jos profeetta olisi määrännyt sinulle jotakin erinomaista, etkö tekisi sitä? Saati sitten, kun hän sanoi sinulle ainoastaan: \'Peseydy, niin tulet puhtaaksi.\'"',
        14: 'Hän meni ja kastoi itsensä Jordanissa seitsemän kertaa, niin kuin Jumalan mies oli sanonut. Hänen lihansa tuli entiselleen, pienen pojan lihan kaltaiseksi, ja hän tuli puhtaaksi.',
        15: 'Sitten hän palasi Jumalan miehen luo, hän ja koko hänen joukkonsa, meni sisälle, astui hänen eteensä ja sanoi: "Katso, nyt tiedän, ettei Jumalaa ole missään muualla maan päällä kuin Israelissa. Ota siis vastaan jäähyväislahja palvelijaltasi."',
        16: 'Mutta hän vastasi: "Niin totta kuin Herra elää, jonka edessä seison, en sitä ota." Naeman pyytämällä pyysi häntä ottamaan, mutta hän epäsi.',
        17: 'Niin Naeman sanoi: "Jos et tätä otakaan, salli kuitenkin palvelijasi saada sen verran maata, kuin muulipari voi kantaa. Sillä palvelijasi ei enää uhraa polttouhria eikä teurasuhria muille jumalille kuin Herralle.',
        18: 'Tämän antakoon kuitenkin Herra anteeksi palvelijallesi: kun herrani menee Rimmonin temppeliin rukoilemaan nojaten käteeni, ja minäkin kumarrun Rimmonin temppelissä, niin antakoon Herra palvelijallesi anteeksi sen, että kumarrun Rimmonin temppelissä."',
        19: 'Elisa sanoi hänelle: "Mene rauhassa." Kun hän oli kulkenut hänen luotaan jonkin matkaa,',
        20: 'ajatteli Geehasi, Jumalan miehen Elisan palvelija: "Katso, minun herrani säästi tuota aramilaista Naemania, niin ettei ottanut häneltä, mitä hän oli tuonut. Niin totta kuin Herra elää, riennän hänen jälkeensä ja otan häneltä jotakin."',
        21: 'Geehasi juoksi Naemanin jälkeen. Kun Naeman näki hänen rientävän jäljessään, hän hyppäsi alas vaunuistaan, meni häntä vastaan ja kysyi: "Onko kaikki hyvin?"',
        22: 'Hän vastasi: "Hyvin on, mutta herrani on lähettänyt minut ja käskee sanoa: \'Nyt juuri tuli luokseni Efraimin vuoristosta kaksi nuorta miestä, profeetanoppilaita. Anna heille talentti hopeaa ja kaksi juhlapukua.\'"',
        23: 'Naeman vastasi: "Suvaitse ottaa kaksi talenttia." Hän pyytämällä pyysi häntä. Hän sitoi kaksi talenttia hopeaa kahteen kukkaroon ja antoi ne sekä kaksi juhlapukua kahdelle palvelijalleen, ja he kantoivat niitä hänen edellään.',
        24: 'Mutta kun hän tuli kummulle, hän otti ne heidän käsistään ja kätki ne taloon ja päästi miehet menemään.',
        25: 'Sitten hän meni sisälle ja astui herransa luo. Niin Elisa kysyi häneltä: "Mistä tulet, Geehasi?" Hän vastasi: "Palvelijasi ei ole käynyt missään."',
        26: 'Elisa sanoi hänelle: "Eikö henkeni kulkenut kanssasi, kun eräs mies kääntyi vaunuissaan sinua vastaan? Oliko nyt aika ottaa hopeaa ja hankkia vaatteita, öljytarhoja, viinitarhoja, lampaita, nautoja, palvelijoita ja palvelijattaria?',
        27: 'Naemanin spitaali tarttuu sinuun ja sinun jälkeläisiisi ikiajoiksi." Niin Geehasi lähti hänen luotaan lumivalkeana spitaalista.',
    },
    6: {
        1: 'Profeetanoppilaat sanoivat Elisalle: "Katso, huone, jossa istumme edessäsi, on meille liian ahdas.',
        2: 'Menkäämme siis Jordanille ja tuokaamme sieltä kukin yksi hirsi ja rakentakaamme sinne huone, missä voimme istua." Hän sanoi: "Menkää."',
        3: 'Eräs heistä sanoi: "Suvaitse tulla palvelijasi kanssa." Hän sanoi: "Minä tulen."',
        4: 'Niin hän meni heidän kanssaan. Jordanille tultuaan he hakkasivat puita.',
        5: 'Mutta erään heistä kaataessa puuta kirposi kirves veteen. Niin hän huusi ja sanoi: "Voi, herrani, se oli vielä lainattu!"',
        6: 'Jumalan mies kysyi: "Mihin se kirposi?" Niin hän näytti hänelle paikan. Silloin hän veisti puupalan ja heitti sen siihen ja sai kirveen nousemaan pinnalle.',
        7: 'Sitten hän sanoi: "Nosta se ylös." Mies ojensi kätensä ja otti sen.',
        8: 'Kun Aramin kuningas oli sodassa Israelia vastaan, hän neuvotteli palvelijoidensa kanssa ja sanoi: "Siihen ja siihen paikkaan asetun leiriin."',
        9: 'Mutta Jumalan mies lähetti Israelin kuninkaalle sanan: "Varo, ettet mene siihen paikkaan, sillä aramilaiset ovat asettuneet sinne."',
        10: 'Israelin kuningas lähetti sanan siihen paikkaan, jonka Jumalan mies oli hänelle sanonut. Näin tämä varoitti häntä, ja hän oli siellä varuillaan. Eikä se tapahtunut ainoastaan kerran tai kahdesti.',
        11: 'Aramin kuninkaan sydän tuli tästä levottomaksi, ja hän kutsui palvelijansa ja sanoi heille: "Ettekö voi ilmaista minulle, kuka meikäläisistä pitää Israelin kuninkaan puolta?"',
        12: 'Silloin eräs hänen palvelijoistaan sanoi: "Ei niin, herrani, kuningas, vaan profeetta Elisa, joka on Israelissa, ilmaisee Israelin kuninkaalle nekin sanat, jotka puhut makuuhuoneessasi."',
        13: 'Hän sanoi: "Menkää ja katsokaa, missä hän on, niin lähetän ottamaan hänet kiinni." Hänelle ilmoitettiin: "Katso, hän on Dootanissa."',
        14: 'Hän lähetti sinne hevosia ja sotavaunuja ja suuren sotajoukon. He tulivat sinne yöllä ja ympäröivät kaupungin.',
        15: 'Kun Jumalan miehen palvelija nousi aamulla varhain ja meni ulos, katso, sotajoukko, hevoset ja sotavaunut piirittivät kaupunkia. Hänen palvelijansa sanoi hänelle: "Voi, herrani, mitä me nyt teemme?"',
        16: 'Hän sanoi: "Älä pelkää, sillä niitä, jotka ovat kanssamme, on enemmän kuin niitä, jotka ovat heidän kanssaan."',
        17: 'Elisa rukoili ja sanoi: " Herra, avaa hänen silmänsä, että hän näkisi." Herra avasi palvelijan silmät, ja hän näki, ja katso: vuori oli täynnä tulisia hevosia ja tulisia vaunuja Elisan ympärillä.',
        18: 'Kun viholliset sitten tulivat häntä vastaan, Elisa rukoili Herraa ja sanoi: "Sokaise tämä väki." Hän sokaisi heidät Elisan pyynnön mukaan.',
        19: 'Elisa sanoi heille: "Ei tämä ole oikea tie, eikä tämä ole oikea kaupunki. Seuratkaa minua, niin minä vien teidät sen miehen luo, jota te etsitte." Sitten hän vei heidät Samariaan.',
        20: 'Mutta kun he tulivat Samariaan, Elisa sanoi: " Herra, avaa näiden silmät, että he näkisivät." Silloin Herra avasi heidän silmänsä, ja he näkivät, ja katso: he olivat keskellä Samariaa.',
        21: 'Kun Israelin kuningas näki heidät, hän sanoi Elisalle: "Surmaanko heidät, isäni, surmaanko heidät?"',
        22: 'Hän sanoi: "Älä surmaa. Surmaatko ne, jotka otat vangiksi miekallasi ja jousellasi? Pane heidän eteensä ruokaa ja juomaa heidän syödä ja juoda. Menkööt sitten takaisin herransa luo."',
        23: 'Tämä valmisti heille suuren aterian, ja kun he olivat syöneet ja juoneet, hän päästi heidät menemään, ja he menivät herransa luo. Aramilaisia partiojoukkoja ei enää tullut Israelin maahan.',
        24: 'Sen jälkeen Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa ja tuli ja piiritti Samarian.',
        25: 'Silloin syntyi Samariassa heidän sitä piirittäessään suuri nälänhätä, niin että aasinpää maksoi kahdeksankymmentä hopeasekeliä ja neljännes kab-mittaa kyyhkysen lantaa viisi hopeasekeliä.',
        26: 'Kun Israelin kuningas käveli muurin päällä, huusi muuan nainen hänelle ja sanoi: "Auta, herrani, kuningas."',
        27: 'Hän vastasi: "Ellei Herra auta sinua, niin mistä minä hankin sinulle apua? Puimatantereeltako vai viinikuurnasta?"',
        28: 'Kuningas sanoi hänelle: "Mikä sinun on?" Hän vastasi: "Tämä nainen sanoi minulle: \'Anna tänne poikasi syödäksemme hänet tänä päivänä, niin syömme huomenna minun poikani.\'',
        29: 'Me keitimme minun poikani ja söimme hänet. Minä sanoin toisena päivänä hänelle: \'Anna tänne poikasi syödäksemme hänet.\' Mutta hän piilotti poikansa."',
        30: 'Kun kuningas kuuli naisen sanat, hän repäisi vaatteensa kävellessään muurin päällä. Kansa näki, että hänellä oli vaatteiden alla säkki, paljaalla iholla.',
        31: 'Hän sanoi: "Jumala rangaiskoon minua nyt ja vasta, jos Elisan, Saafatin pojan, pää tänä päivänä jää hänen hartioilleen."',
        32: 'Elisa istui talossaan, ja vanhimmat istuivat hänen luonaan. Mutta kuningas oli lähettänyt miehen edellään. Ennen kuin sanansaattaja tuli hänen luokseen, hän sanoi vanhimmille: "Näettekö, kuinka se murhamiehen poika lähettää hakkaamaan minulta päätä poikki? Mutta kun sanansaattaja tulee, katsokaa, että suljette oven ja pidätte oven kiinni häneltä. Eivätkö hänen herransa askeleet kuulu jo hänen perässään?"',
        33: 'Hänen vielä puhuessaan heidän kanssaan tuli sanansaattaja hänen luokseen ja sanoi: "Katso, tämä onnettomuus tulee Herralta, miksi minä enää odottaisin Herraa?"',
    },
    7: {
        1: 'Mutta Elisa vastasi: "Kuulkaa Herran sana. Näin sanoo Herra: Huomenna tähän aikaan maksaa Samarian portissa sea-mitta ydinjauhoja sekelin ja kaksi sea-mittaa ohria sekelin."',
        2: 'Vaunusoturi, jonka käsivarteen kuningas nojasi, vastasi Jumalan miehelle ja sanoi: "Katso, vaikka Herra tekisi ikkunat taivaaseen, kuinka tämä voisi tapahtua?" Hän sanoi: "Sinä olet sen omin silmin näkevä, mutta siitä et syö."',
        3: 'Kaupungin portin oven edustalla oleskeli neljä spitaalista miestä. He sanoivat toisilleen: "Mitä me tässä istumme, kunnes kuolemme?',
        4: 'Jos päätämme mennä kaupunkiin, jossa on nälänhätä, niin kuolemme. Jos jäämme tähän, kuolemme. Tulkaa, siirtykäämme nyt aramilaisten leiriin. Jos he jättävät meidät eloon, jäämme eloon. Jos he surmaavat meidät, kuolemme."',
        5: 'He nousivat hämärissä mennäkseen aramilaisten leiriin. Kun he tulivat aramilaisten leirin laitaan, katso: siellä ei ollut ketään.',
        6: 'Sillä Herra oli antanut aramilaisten sotajoukon kuulla sotavaunujen, hevosten ja suuren sotajoukon töminää, ja niin he olivat sanoneet toisilleen: "Katso, Israelin kuningas on palkannut meitä vastaan heettiläisten kuninkaat ja egyptiläisten kuninkaat käydäkseen meitä vastaan."',
        7: 'He olivat lähteneet liikkeelle ja paenneet hämärissä ja jättäneet telttansa, hevosensa, aasinsa ja leirinsä, niin kuin se oli. He olivat paenneet pelastaakseen henkensä.',
        8: 'Tultuaan leirin laitaan spitaaliset menivät erääseen telttaan, söivät ja joivat, ottivat sieltä hopeaa ja kultaa ja vaatteita, menivät pois ja kätkivät ne. Sitten he tulivat takaisin ja menivät toiseen telttaan ja ottivat sieltä saalista ja menivät pois ja kätkivät sen.',
        9: 'Mutta sitten he sanoivat toisilleen: "Emme tee oikein. Tämä päivä on hyvän sanoman päivä. Jos olemme vaiti ja odotamme aamun valkenemiseen asti joudumme syyllisiksi. Tulkaa, menkäämme nyt ilmoittamaan tämä kuninkaan linnaan."',
        10: 'He tulivat ja kutsuivat kaupungin portinvartijat ja ilmoittivat heille sanoen: "Me tulimme aramilaisten leiriin, ja katso, siellä ei ollut ketään eikä kuulunut ihmisääntä. Siellä oli vain hevosia ja aaseja kytkettyinä kiinni, ja teltat olivat, niin kuin olivat olleet."',
        11: 'Portinvartijat kuuluttivat ja ilmoittivat tämän kuninkaan linnaan.',
        12: 'Silloin kuningas nousi yöllä ja sanoi palvelijoilleen: "Minä sanon teille, minkä aramilaiset meille tekevät. He tietävät meidän kärsivän nälkää, ja sen tähden he ovat poistuneet leiristä ja piiloutuneet kedolle, ajatellen: kun he lähtevät kaupungista, otamme heidät elävinä kiinni ja menemme kaupunkiin."',
        13: 'Mutta eräs hänen palvelijoistaan vastasi ja sanoi: "Otettakoon viisi jäljelle jäänyttä hevosta, jotka ovat vielä täällä jäljellä – niidenhän käy kuitenkin samoin kuin kaiken Israelin joukon, joka on täällä jäljellä, ja samoin kuin kaiken Israelin joukon, joka on hukkunut – ja lähettäkäämme katsomaan."',
        14: 'He ottivat kahdet sotavaunut hevosineen, ja kuningas lähetti ne aramilaisten sotajoukon perään, sanoen: "Menkää ja katsokaa."',
        15: 'He menivät heidän jälkeensä aina Jordanille asti. Katso: koko tie oli täynnä vaatteita ja aseita, jotka aramilaiset olivat heittäneet pois rientäessään pakoon. Sanansaattajat tulivat takaisin ja ilmoittivat sen kuninkaalle.',
        16: 'Silloin kansa lähti ja ryösti aramilaisten leirin. Niin sea-mitta ydinjauhoja maksoi sekelin ja kaksi sea-mittaa ohria sekelin Herran sanan mukaan.',
        17: 'Kuningas oli asettanut sen vaunusoturin, jonka käsivarteen hän nojasi, porttiin valvomaan järjestystä. Mutta kansa tallasi hänet kuoliaaksi portissa, kuten Jumalan mies oli puhunut, silloin kun kuningas tuli hänen luokseen.',
        18: 'Sillä kun Jumalan mies oli puhunut kuninkaalle näin: "Huomenna tähän aikaan maksaa kaksi sea-mittaa ohria Samarian portissa sekelin ja sea-mitta ydinjauhoja sekelin",',
        19: 'vaunusoturi oli vastannut Jumalan miehelle ja sanonut: "Katso, vaikka Herra tekisi ikkunat taivaaseen, kuinka tämä voisi tapahtua?" Silloin hän oli sanonut: "Sinä olet näkevä sen omin silmin, mutta siitä et syö."',
        20: 'Niin hänen myös kävi: kansa tallasi hänet kuoliaaksi portissa.',
    },
    8: {
        1: 'Elisa sanoi naiselle, jonka pojan hän oli palauttanut henkiin, ja sanoi: "Nouse ja lähde, sinä ja perheesi, asumaan muukalaisena, missä vain voit asua, sillä Herra on käskenyt nälänhädän tulla, ja se myös tulee maahan seitsemäksi vuodeksi."',
        2: 'Nainen oli noussut ja tehnyt Jumalan miehen sanan mukaan: hän oli lähtenyt ja asunut perheineen muukalaisena filistealaisten maassa seitsemän vuotta.',
        3: 'Mutta niiden seitsemän vuoden kuluttua nainen palasi filistealaisten maasta. Hän tuli anomaan kuninkaalta taloaan ja peltoaan.',
        4: 'Kuningas puhutteli juuri Geehasia, Jumalan miehen palvelijaa, ja sanoi: "Kerro minulle kaikki ne suuret teot, jotka Elisa on tehnyt."',
        5: 'Juuri kun hän kertoi kuninkaalle, kuinka Elisa oli palauttanut kuolleen henkiin, nainen, jonka pojan hän oli palauttanut henkiin, tuli anomaan kuninkaalta taloaan ja peltoaan. Silloin Geehasi sanoi: "Herrani, kuningas, tämä on se nainen, ja tämä on se poika, jonka Elisa palautti henkiin."',
        6: 'Kuningas kyseli naiselta, ja tämä kertoi sen hänelle. Kuningas antoi hänen mukaansa hoviherran ja sanoi: "Toimita naiselle takaisin kaikki, mikä on hänen omaansa, ja lisäksi kaikki pellon sadot siitä päivästä alkaen, jona hän jätti maan, aina tähän asti."',
        7: 'Elisa tuli Damaskoon. Aramin kuningas Benhadad oli sairaana. Kun hänelle ilmoitettiin: "Jumalan mies on tullut tänne",',
        8: 'kuningas sanoi Hasaelille: "Ota mukaasi lahja ja mene Jumalan miestä vastaan ja kysy hänen kauttaan Herralta: \'Toivunko tästä taudista?\'"',
        9: 'Hasael meni häntä vastaan ja otti mukaansa lahjaksi kaikkea, mitä Damaskossa oli parasta, neljäkymmentä kamelinkuormaa. Hän tuli ja astui hänen eteensä ja sanoi: "Poikasi Benhadad, Aramin kuningas, lähetti minut luoksesi ja käski kysyä: \'Toivunko tästä taudista?\'"',
        10: 'Elisa sanoi: "Mene ja sano hänelle: \'Toivut.\' Mutta Herra on ilmoittanut minulle, että hänen on kuoltava."',
        11: 'Hän tuijotti eteensä kauan ja liikahtamatta, sitten Jumalan mies alkoi itkeä.',
        12: 'Niin Hasael sanoi: "Minkä tähden herrani itkee?" Hän vastasi: "Sen tähden, että tiedän, kuinka paljon pahaa olet tekevä israelilaisille: pistät heidän varustetut kaupunkinsa tuleen, surmaat miekalla heidän sankarinsa, murskaat heidän pienet lapsensa ja halkaiset heidän raskaana olevat vaimonsa."',
        13: 'Hasael sanoi: "Mikä on palvelijasi, tällainen koira, tekemään näitä suuria asioita?" Elisa vastasi: " Herra on ilmoittanut minulle, että sinusta on tuleva Aramin kuningas."',
        14: 'Hän meni Elisan luota, ja kun hän tuli herransa luo, tämä kysyi häneltä: "Mitä Elisa sanoi sinulle?" Hän vastasi: "Hän sanoi minulle, että toivut."',
        15: 'Mutta seuraavana päivänä hän otti peitteen ja kastoi sen veteen ja levitti sen hänen kasvoilleen. Niin hän kuoli. Hasael tuli kuninkaaksi hänen jälkeensä.',
        16: 'Israelin kuninkaan Jooramin, Ahabin pojan, viidentenä hallitusvuotena tuli Jooram, Juudan kuninkaan Joosafatin poika, kuninkaaksi.',
        17: 'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.',
        18: 'Mutta hän vaelsi Israelin kuningasten tietä, niin kuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär. Hän teki sitä, mikä on pahaa Herran silmissä.',
        19: 'Mutta palvelijansa Daavidin tähden Herra ei tahtonut tuhota Juudaa, koska hän oli luvannut antaa hänelle ja hänen pojilleen lampun ainiaaksi.',
        20: 'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itselleen kuninkaan.',
        21: 'Jooram lähti Saairiin kaikkine sotavaunuineen. Hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, sekä sotavaunujen päälliköt. Mutta väki pakeni teltoilleen.',
        22: 'Edomilaiset luopuivat Juudan vallanalaisuudesta aina tähän päivään asti. Siihen aikaan luopui myös Libna.',
        23: 'Mitä muuta on kerrottavaa Jooramista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        24: 'Sitten Jooram meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Ahasja tuli kuninkaaksi hänen jälkeensä.',
        25: 'Israelin kuninkaan Jooramin, Ahabin pojan, kahdentenatoista hallitusvuotena tuli kuninkaaksi Ahasja, Juudan kuninkaan Jooramin poika.',
        26: 'Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Israelin kuninkaan Omrin tytär.',
        27: 'Ahasja vaelsi Ahabin suvun tietä ja teki sitä, mikä on pahaa Herran silmissä, samoin kuin Ahabin suku, sillä hän oli lankoutunut Ahabin suvun kanssa.',
        28: 'Hän lähti Jooramin, Ahabin pojan, kanssa sotimaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin, mutta aramilaiset haavoittivat Jooramia.',
        29: 'Niin kuningas Jooram tuli takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ahasja, Jooramin poika, Juudan kuningas, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairas.',
    },
    9: {
        1: 'Profeetta Elisa kutsui erään profeetanoppilaan ja sanoi hänelle: "Vyötä kupeesi ja ota tämä öljyastia mukaasi ja mene Gileadin Raamotiin.',
        2: 'Tultuasi sinne hae sieltä käsiisi Jeehu, Joosafatin poika, Nimsin pojanpoika. Mene sisälle, käske hänen nousta toveriensa keskeltä ja vie hänet sisimpään huoneeseen.',
        3: 'Ota sitten öljyastia, vuodata öljyä hänen päähänsä ja sano: \'Näin sanoo Herra: Olen voidellut sinut Israelin kuninkaaksi.\' Avaa sitten ovi ja pakene viivyttelemättä."',
        4: 'Niin nuorukainen, profeetan palvelija, meni Gileadin Raamotiin.',
        5: 'Kun hän tuli sinne, katso: sotaväen päälliköt istuivat siellä. Hän sanoi: "Minulla on asiaa sinulle, päällikkö." Jeehu kysyi: "Kenelle meistä kaikista?" Hän vastasi: "Sinulle itsellesi, päällikkö."',
        6: 'Silloin tämä nousi ja meni sisälle huoneeseen, ja hän vuodatti öljyä tämän päähän ja sanoi hänelle: "Näin sanoo Herra, Israelin Jumala: Olen voidellut sinut Herran kansan, Israelin, kuninkaaksi.',
        7: 'Sinä olet surmaava herrasi Ahabin suvun, sillä kostan Iisebelille palvelijoitteni, profeettojen, veren ja kaikkien Herran palvelijoiden veren.',
        8: 'Koko Ahabin suku on tuhoutuva: hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.',
        9: 'Teen Ahabin suvulle saman, minkä Jerobeamin, Nebatin pojan, suvulle ja saman, minkä Baesan, Ahian pojan, suvulle.',
        10: 'Koirat syövät Iisebelin Jisreelin vainiolla, eikä kukaan ole hautaava häntä." Sitten hän avasi oven ja pakeni.',
        11: 'Kun Jeehu tuli ulos herransa palvelijoiden luo, häneltä kysyttiin: "Onko kaikki hyvin? Miksi tuo hullu kävi luonasi?" Hän vastasi heille: "Tehän tunnette miehen ja hänen puheensa."',
        12: 'Mutta he sanoivat: "Valetta! Sano meille totuus." Hän sanoi: "Niin ja niin hän puhui minulle ja sanoi: \'Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi.\'"',
        13: 'He ottivat kiireen vilkkaa kukin vaatteensa ja panivat ne hänen alleen paljaille portaille, puhalsivat torveen ja huusivat: "Jeehu on tullut kuninkaaksi."',
        14: 'Jeehu, Joosafatin poika, Nimsin pojanpoika, teki salaliiton Jooramia vastaan. Jooram oli ollut koko Israelin kanssa puolustamassa Gileadin Raamotia Hasaelia, Aramin kuningasta, vastaan.',
        15: 'Mutta kuningas Jooram oli tullut takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Jeehu sanoi: "Jos se teille kelpaa, älkää päästäkö pakoon kaupungista ketään, joka menisi ilmoittamaan tätä Jisreeliin."',
        16: 'Jeehu nousi vaunuihinsa ja lähti Jisreeliin, sillä Jooram makasi siellä, ja Ahasja, Juudan kuningas, oli tullut sinne katsomaan Jooramia.',
        17: 'Mutta tähystäjä seisoi Jisreelin tornissa, ja kun hän näki Jeehun joukon tulevan, hän sanoi: "Minä näen väkijoukon." Niin Jooram sanoi: "Otettakoon ratsumies ja lähetettäköön heitä vastaan kysymään, onko kaikki hyvin."',
        18: 'Ratsumies lähti häntä vastaan ja sanoi: "Näin kysyy kuningas: \'Onko kaikki hyvin?\'" Jeehu vastasi: "Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua." Niin tähystäjä ilmoitti sanoen: "Sanansaattaja on tullut heidän luokseen, mutta ei palaa."',
        19: 'Hän lähetti toisen ratsumiehen. Kun tämä oli tullut heidän luokseen, hän sanoi: "Näin kysyy kuningas: \'Onko kaikki hyvin?\'" Jeehu vastasi: "Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua."',
        20: 'Tähystäjä ilmoitti sanoen: "Hän on tullut heidän luokseen, mutta ei palaa, ja ajo on aivan kuin Jeehun, Nimsin pojan, ajoa. Sillä hän ajaa kuin hurjapää."',
        21: 'Silloin Jooram sanoi: "Valjastettakoon!" He valjastivat hänen sotavaununsa. Jooram, Israelin kuningas, ja Ahasja, Juudan kuningas, lähtivät kumpikin sotavaunuissaan ja menivät Jeehua vastaan. He kohtasivat hänet jisreeliläisen Naabotin maapalstalla.',
        22: 'Kun Jooram näki Jeehun, hän kysyi: "Onko kaikki hyvin, Jeehu?" Tämä vastasi: "Kuinka kaikki voisi olla hyvin, kun äitisi Iisebelin haureus ja hänen monet velhoutensa yhä vielä jatkuvat?"',
        23: 'Silloin Jooram käänsi vaununsa ja pakeni, huutaen Ahasjalle: "Kavallus, Ahasja!"',
        24: 'Mutta Jeehu sieppasi jousen käteensä ja ampui Jooramia hartioiden väliin, niin että nuoli meni sydämen lävitse, ja hän vaipui vaunuihinsa.',
        25: 'Hän sanoi Bidkarille, vaunusoturille: "Ota hänet ja heitä jisreeliläisen Naabotin maapalstalle, sillä muistathan, että Herra meidän ratsastaessamme rinnakkain hänen isänsä Ahabin jäljessä lausui hänestä tämän ennustuksen:',
        26: '\'Totisesti, minä näin eilen Naabotin ja hänen poikiensa veren, sanoo Herra, ja minä olen juuri tällä maapalstalla kostava sinulle, sanoo Herra.\' Ota siis hänet ja heitä tälle maapalstalle, Herran sanan mukaan."',
        27: 'Kun Ahasja, Juudan kuningas, näki sen, hän pakeni Beet-Gaaniin päin. Mutta Jeehu ajoi häntä takaa ja sanoi: "Ampukaa hänetkin vaunuihinsa." He ampuivat häntä Guurin solassa, joka on Jibleamin luona, mutta hän pakeni Megiddoon ja kuoli siellä.',
        28: 'Hänen palvelijansa veivät hänet vaunuissa Jerusalemiin ja hautasivat hänet hänen omaan hautaansa, hänen isiensä viereen, Daavidin kaupunkiin.',
        29: 'Ahasja oli tullut Juudan kuninkaaksi Jooramin, Ahabin pojan, yhdentenätoista hallitusvuotena.',
        30: 'Jeehu tuli Jisreeliin. Kun Iisebel kuuli sen, hän maalasi ihomaalilla silmäluomensa, koristeli päänsä ja katseli ulos ikkunasta.',
        31: 'Kun Jeehu tuli portista sisään, Iisebel kysyi: "Kävikö hyvin Simrille, herransa murhaajalle?"',
        32: 'Hän käänsi kasvonsa ikkunaa kohti ja sanoi: "Kuka on minun puolellani? Kuka?" Niin pari kolme hoviherraa katsoi alas häneen.',
        33: 'Jeehu sanoi: "Syöskää hänet alas." Niin he syöksivät hänet alas, niin että hänen vertaan roiskui seinään ja hevosiin, ja ne tallasivat hänet jalkoihinsa.',
        34: 'Sitten Jeehu meni sisään, söi ja joi. Hän sanoi: "Korjatkaa se kirottu ja haudatkaa hänet, sillä onhan hän kuninkaan tytär."',
        35: 'Mutta kun he menivät hautaamaan häntä, he eivät löytäneet hänestä muuta kuin pääkallon, jalat ja kädet.',
        36: 'He tulivat takaisin ja ilmoittivat sen Jeehulle. Hän sanoi: "Tässä on toteutunut Herran sana, jonka hän puhui palvelijansa tisbeläisen Elian kautta: \'Jisreelin vainiolla koirat syövät Iisebelin lihan,',
        37: 'ja Iisebelin ruumis on oleva kuin pellon lantaa Jisreelin vainiolla, niin ettei voida sanoa: Tämä on Iisebel.\'"',
    },
    10: {
        1: 'Mutta Ahabilla oli seitsemänkymmentä poikaa Samariassa. Jeehu kirjoitti kirjeet ja lähetti ne Samariaan, Jisreelin päämiehille, vanhimmille ja Ahabin poikien holhoojille. Hän kirjoitti näin:',
        2: '"Kun tämä kirje tulee teille, joiden hallussa herranne pojat ovat ja joiden hallussa ovat sotavaunut, hevoset, varustettu kaupunki ja aseet,',
        3: 'valitkaa herranne pojista paras ja oikeamielisin ja asettakaa hänet isänsä valtaistuimelle ja sotikaa herranne suvun puolesta."',
        4: 'Mutta he pelästyivät kovin ja sanoivat: "Katso, ne kaksi kuningasta eivät kestäneet hänen edessään, kuinka me kestäisimme?"',
        5: 'Linnan päällikkö ja kaupungin päällikkö sekä vanhimmat ja holhoojat lähettivät Jeehulle sanan: "Olemme palvelijoitasi. Teemme kaiken, mitä meille määräät. Emme tee ketään kuninkaaksi. Tee, mitä tahdot."',
        6: 'Hän kirjoitti heille toisen kirjeen, joka kuului näin: "Jos te olette puolellani ja kuulette minua, ottakaa herranne poikien päät ja tulkaa huomenna tähän aikaan luokseni Jisreeliin." Ne seitsemänkymmentä kuninkaan poikaa asuivat näet kaupungin ylimysten luona, jotka kasvattivat heitä.',
        7: 'Kun kirje tuli heille, he ottivat kuninkaan pojat ja tappoivat heidät, seitsemänkymmentä miestä, panivat heidän päänsä koreihin ja lähettivät ne Jeehulle Jisreeliin.',
        8: 'Sanansaattaja tuli ja ilmoitti hänelle sanoen: "He ovat tuoneet kuninkaan poikien päät." Hän sanoi: "Pankaa ne kahteen kasaan portin oven edustalle huomiseen saakka."',
        9: 'Aamulla hän meni ulos, asettui siihen ja sanoi kaikelle kansalle: "Te olette syyttömät. Katso, minä olen tehnyt salaliiton herraani vastaan ja tappanut hänet. Mutta kuka on surmannut nämä kaikki?',
        10: 'Tietäkää siis, ettei ainoakaan Herran sana, jonka Herra on puhunut Ahabin sukua vastaan, putoa maahan. Herra on tehnyt, minkä hän on puhunut palvelijansa Elian kautta."',
        11: 'Jeehu surmasi kaikki, jotka olivat Ahabin suvusta jäljellä Jisreelissä, sekä kaikki hänen ylimyksensä, uskottunsa ja pappinsa päästämättä pakoon ainoatakaan.',
        12: 'Hän nousi ja lähti Samariaan. Mutta tullessaan paimenten Beet-Eekediin, joka on tien varrella,',
        13: 'Jeehu kohtasi Ahasjan, Juudan kuninkaan, veljet ja kysyi: "Keitä te olette?" He vastasivat: "Me olemme Ahasjan veljiä ja menemme tervehtimään kuninkaan poikia ja kuninkaan äidin poikia."',
        14: 'Hän sanoi: "Ottakaa nämä elävinä kiinni." He ottivat heidät elävinä kiinni ja tappoivat heidät ja heittivät Beet-Eekedin vesisäiliöön, neljäkymmentä kaksi miestä. Hän ei jättänyt heistä ainoatakaan eloon.',
        15: 'Kun hän lähti sieltä, kohtasi hän Joonadabin, Reekabin pojan, joka tuli häntä vastaan. Hän tervehti häntä ja sanoi hänelle: "Onko sydämesi yhtä vilpitön minua kohtaan, kuin sydämeni on sinua kohtaan?" Joonadab vastasi: "On." – "Jos niin on, lyö kättä kanssani." Hän löi kättä, ja hän otti hänet vaunuihinsa.',
        16: 'Hän sanoi: "Lähde kanssani katsomaan kiivailuani Herran puolesta." Ja hän ajoi hänen vaunuissaan.',
        17: 'Tultuaan Samariaan hän surmasi kaikki, jotka olivat Ahabin jälkeläisistä jäljellä Samariassa, kunnes hän oli hävittänyt hänen sukunsa, Herran sanan mukaan, jonka Herra oli puhunut Elialle.',
        18: 'Sitten Jeehu kokosi kaiken kansan ja sanoi heille: "Ahab on palvellut Baalia vähän. Jeehu on palveleva häntä paljon.',
        19: 'Kutsukaa nyt luokseni kaikki Baalin profeetat, kaikki hänen palvelijansa ja kaikki hänen pappinsa, älköönkä kukaan jääkö pois, sillä aion uhrata suuret uhrit Baalille. Eloon ei jää kukaan, joka jää pois." Mutta Jeehu menetteli kavalasti tuhotakseen Baalin palvelijat.',
        20: 'Jeehu sanoi: "Kuuluttakaa pyhä juhlakokous Baalin kunniaksi." Se kutsuttiin koolle.',
        21: 'Jeehu lähetti sanan kaikkeen Israeliin, ja kaikki Baalin palvelijat tulivat. Yksikään ei jäänyt tulematta. He menivät Baalin temppeliin, ja Baalin temppeli täyttyi ääriään myöten.',
        22: 'Hän sanoi vaatekammion hoitajalle: "Tuo puvut kaikille Baalin palvelijoille." Tämä toi heille puvut.',
        23: 'Kun Jeehu Joonadabin, Reekabin pojan, kanssa tuli Baalin temppeliin, hän sanoi Baalin palvelijoille: "Tutkikaa ja katsokaa, ettei täällä joukossanne ole ketään Herran palvelijaa, vaan ainoastaan Baalin palvelijoita."',
        24: 'He menivät uhraamaan teurasuhreja ja polttouhreja. Mutta Jeehu oli asettanut ulkopuolelle kahdeksankymmentä miestä ja sanonut: "Jos kuka päästää pakoon yhdenkään niistä miehistä, jotka tuon teidän käsiinne, menee henki hengestä."',
        25: 'Päätettyään polttouhrin uhraamisen Jeehu sanoi henkivartijoille ja vaunusotureille: "Menkää sisään ja surmatkaa heidät, älköön yksikään pääskö ulos." He surmasivat heidät miekan terällä, ja henkivartijat ja vaunusoturit heittivät heidän ruumiinsa ulos. Sitten he menivät Baalin temppelilinnaan',
        26: 'ja toivat ulos Baalin temppelin patsaat ja polttivat ne,',
        27: 'ja he kukistivat Baalin patsaan. He hävittivät Baalin temppelin ja tekivät siitä käymälöitä. Niin on aina tähän päivään asti.',
        28: 'Näin Jeehu hävitti Baalin Israelista.',
        29: 'Mutta Jerobeamin, Nebatin pojan, synneistä, joilla hän oli saattanut Israelin tekemään syntiä, Beetelissä ja Daanissa olevista kultavasikoista, Jeehu ei luopunut.',
        30: 'Herra sanoi Jeehulle: "Koska olet hyvin toimittanut sen, mikä oli oikein silmissäni, ja koska teit Ahabin suvulle aivan mieleni mukaan, niin istukoot poikasi Israelin valtaistuimella neljänteen polveen."',
        31: 'Mutta Jeehu ei vaeltanut tarkasti, kaikesta sydämestään, Herran, Israelin Jumalan, lain mukaan. Hän ei luopunut Jerobeamin synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        32: 'Niihin aikoihin Herra rupesi lohkomaan Israelia, sillä Hasael voitti heidät kaikkialla Israelin raja-alueella',
        33: 'ja valloitti Jordanista auringonnousuun päin koko Gileadin maan, gaadilaiset, ruubenilaiset ja manasselaiset, alkaen Aroerista, joka on Arnon-joen rannalla – sekä Gileadin että Baasanin.',
        34: 'Mitä muuta on kerrottavaa Jeehusta ja kaikesta, mitä hän teki, ja kaikista hänen urotöistään, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        35: 'Jeehu meni lepoon isiensä luo, ja hänet haudattiin Samariaan. Hänen poikansa Jooahas tuli kuninkaaksi hänen jälkeensä.',
        36: 'Aika, jonka Jeehu hallitsi Israelia Samariassa, oli kaksikymmentä kahdeksan vuotta.',
    },
    11: {
        1: 'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, hän nousi ja tuhosi koko kuningassuvun.',
        2: 'Mutta kuningas Jooramin tytär Jooseba, Ahasjan sisar, otti surmattavien kuninkaan poikien joukosta Ahasjan pojan Jooaan ja vei hänet ja hänen imettäjänsä salaa makuuhuoneeseen. Täällä pidettiin Jooasta kätkettynä Ataljalta, niin ettei hän tullut surmatuksi.',
        3: 'Sitten poika oli Jooseban luona Herran temppeliin piilotettuna kuusi vuotta Ataljan hallitessa maata.',
        4: 'Mutta seitsemäntenä vuotena Joojada lähetti hakemaan kaarilaisten ja henkivartijoiden sadanpäämiehiä ja tuotti heidät luokseen Herran temppeliin. Kun hän oli tehnyt liiton heidän kanssaan ja vannottanut heidät siellä Herran temppelissä, hän näytti heille kuninkaan pojan.',
        5: 'Hän käski heitä sanoen: "Tehkää näin: kolmas osa teistä, joiden on mentävä vartioon sapattina, vartioikoon kuninkaan palatsia,',
        6: 'kolmas osa olkoon sivuportilla ja kolmas osa henkivartijoiden takana olevalla portilla. Vartioikaa kukin vuorollanne palatsia.',
        7: 'Mutta kaksi muuta teidän osastoanne, kaikki, jotka pääsevät vartionpidosta sapattina, vartioikoot Herran temppeliä kuninkaan luona.',
        8: 'Asettukaa kuninkaan ympärille, kullakin ase kädessä. Joka tunkeutuu rivien läpi, surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään."',
        9: 'Sadanpäämiehet tekivät, aivan kuten pappi Joojada oli heitä käskenyt: kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartioon sapattina, että ne, jotka pääsivät vartiosta sapattina, ja he tulivat pappi Joojadan luo.',
        10: 'Pappi antoi sadanpäämiehille keihäät ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Herran temppelissä.',
        11: 'Henkivartijat asettuivat, kullakin ase kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.',
        12: 'Sitten hän toi kuninkaan pojan esille, pani hänen päähänsä kruunun ja antoi hänelle lain kirjan, ja he tekivät hänet kuninkaaksi, voitelivat hänet, paukuttivat käsiään ja huusivat: "Eläköön kuningas!"',
        13: 'Kun Atalja kuuli henkivartijoiden ja kansan huudon, hän meni kansan luo Herran temppeliin.',
        14: 'Hän näki kuninkaan seisovan pylvään vieressä, kuten tapana oli, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin. Atalja repäisi vaatteensa ja huusi: "Kapina! Kapina!"',
        15: 'Mutta pappi Joojada käski sadanpäämiehiä, sotajoukon johtajia, ja sanoi heille: "Viekää hänet pois rivien välitse, ja se, joka yrittää seurata häntä, surmatkaa miekalla." Sillä pappi oli sanonut: "Älköön häntä surmattako Herran temppelissä."',
        16: 'He kävivät häneen käsiksi, ja kun hän oli tullut tielle, jota myöten hevosia kuljetettiin kuninkaan palatsiin, surmattiin hänet palatsissa.',
        17: 'Joojada teki liiton Herran, kuninkaan ja kansan kanssa, että he olisivat Herran kansa, niin myös [liiton] kuninkaan ja kansan kanssa.',
        18: 'Koko maan kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he löivät aivan murskaksi ja tappoivat alttarien edessä Mattanin, Baalin papin. Sitten pappi asetti vartijat vartioimaan Herran temppeliä.',
        19: 'Hän otti mukaansa sadanpäämiehet sekä kaarilaiset, henkivartijat ja kaiken maan kansan, ja he veivät kuninkaan Herran temppelistä ja tulivat henkivartijoiden portin kautta kuninkaan linnaan, ja hän istui kuninkaalliselle valtaistuimelle.',
        20: 'Kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he olivat surmanneet miekalla kuninkaan linnassa.',
    },
    12: {
        1: 'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi.',
        2: 'Jeehun seitsemäntenä hallitusvuotena tuli Jooas kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä oli nimeltään Sibja Beersebasta.',
        3: 'Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin hän eli, sillä pappi Joojada oli opettanut häntä.',
        4: 'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.',
        5: 'Jooas sanoi papeille: "Kaiken rahan, joka pyhinä lahjoina tuodaan Herran temppeliin, käyvän rahan, kaiken arvion mukaan suoritettavan henkilörahan ja kaiken rahan, jonka joku sydämensä vaatimuksesta tuo Herran temppeliin,',
        6: 'papit ottakoot itselleen, kukin tuttavaltaan. Mutta heidän on niillä korjattava, mitä on rappeutunutta Herran temppelissä, missä vain on jotakin rappeutunutta."',
        7: 'Mutta vielä kuningas Jooaan kahdentenakymmenentenä kolmantena hallitusvuotena papit eivät olleet korjanneet mitään, mikä temppelissä oli rappeutunutta.',
        8: 'Kuningas Jooas kutsui pappi Joojadan ja muut papit ja sanoi heille: "Miksi te ette ole korjanneet mitään, mikä temppelissä on rappeutunutta? Nyt te ette enää saa ottaa rahaa tuttaviltanne, vaan teidän on annettava se siihen, mikä temppelissä on rappeutunutta."',
        9: 'Papit suostuivat siihen, etteivät ota rahaa kansalta paitsi korjatakseen sitä, mikä temppelissä oli rappeutunutta.',
        10: 'Pappi Joojada otti arkun ja kaivoi reiän sen kanteen ja asetti sen alttarin ääreen, oikealle puolelle, kun mennään Herran temppeliin. Papit, jotka vartioivat ovea, panivat siihen kaiken rahan, mikä tuotiin Herran temppeliin.',
        11: 'Kun he näkivät, että arkussa oli paljon rahaa, meni kuninkaan kirjuri sinne ylimmäisen papin kanssa. He panivat rahat säkkeihin ja laskivat rahat, jotka olivat Herran temppelissä.',
        12: 'Sitten punnitut rahat annettiin työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä. He maksoivat niillä puusepät ja rakentajat, jotka tekivät työtä Herran temppelissä,',
        13: 'sekä muurarit ja kivenhakkaajat, myös puutavarat ja hakatut kivet, jotka oli ostettava sen korjaamiseksi, mikä Herran temppelissä oli rappeutunutta, kaikki temppelin korjausmenot.',
        14: 'Kuitenkaan Herran temppeliin ei teetetty hopeavateja, veitsiä, maljoja, torvia eikä mitään kulta- tai hopeaesineitä sillä rahalla, joka tuotiin Herran temppeliin,',
        15: 'vaan se annettiin työmiehille, että he sillä korjaisivat Herran temppeliä.',
        16: 'Miehiltä, joille rahat luovutettiin työmiehille annettaviksi, ei vaadittu tilintekoa, vaan he toimivat luottamusmiehinä.',
        17: 'Vikauhri- ja syntiuhrirahoja ei tuotu Herran temppeliin. Ne tulivat papeille.',
        18: 'Siihen aikaan Hasael, Aramin kuningas, tuli ja ryhtyi sotimaan Gatia vastaan ja valloitti sen. Sitten Hasael kävi hyökkäämään Jerusalemia vastaan.',
        19: 'Jooas, Juudan kuningas, otti kaikki pyhät lahjat, jotka hänen isänsä, Juudan kuninkaat Joosafat, Jooram ja Ahasja, olivat pyhittäneet, ja omat pyhät lahjansa sekä kaiken kullan, mitä oli Herran temppelin aarrekammioissa ja kuninkaan linnassa, ja lähetti ne Hasaelille, Aramin kuninkaalle. Tämä lähti pois Jerusalemin kimpusta.',
        20: 'Mitä muuta on kerrottavaa Jooaasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        21: 'Mutta hänen palvelijansa nousivat ja tekivät salaliiton ja surmasivat Jooaan Millossa olevassa rakennuksessa, siinä, mistä mennään alas Sillaan.',
        22: 'Hänen palvelijansa Joosakar, Simeatin poika, ja Joosabad, Soomerin poika, löivät hänet kuoliaaksi, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Amasja tuli kuninkaaksi hänen jälkeensä.',
    },
    13: {
        1: 'Juudan kuninkaan Jooaan, Ahasjan pojan, kahdentenakymmenentenä kolmantena hallitusvuotena tuli Jooahas, Jeehun poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa seitsemäntoista vuotta.',
        2: 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin, Nebatin pojan, synneissä, joilla tämä oli saattanut Israelin tekemään syntiä. Hän ei luopunut niistä.',
        3: 'Herran viha syttyi Israelia kohtaan, ja hän antoi heidät Hasaelin, Aramin kuninkaan, ja Benhadadin, Hasaelin pojan, käsiin koko siksi ajaksi.',
        4: 'Mutta Jooahas lepytti Herraa, ja Herra kuuli häntä, sillä hän näki Israelin sorron, kun Aramin kuningas sorti heitä.',
        5: 'Herra antoi Israelille vapauttajan, ja he pääsivät aramilaisten käsistä. Israelilaiset asuivat teltoissaan kuten ennenkin.',
        6: 'He eivät kuitenkaan luopuneet Jerobeamin suvun synneistä, joilla hän oli saattanut Israelin tekemään syntiä, vaan he vaelsivat niissä. Aserakin jäi paikoilleen Samariaan.',
        7: 'Herra ei jättänyt Jooahaalle väkeä enempää kuin viisikymmentä ratsumiestä, kymmenen sotavaunua ja kymmenentuhatta jalkamiestä. Sillä Aramin kuningas oli hävittänyt ne ja pannut ne tomuksi, niin kuin puitaessa pölyää.',
        8: 'Mitä muuta on kerrottavaa Jooahaasta, kaikesta, mitä hän teki, ja hänen urotöistään, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        9: 'Sitten Jooahas meni lepoon isiensä luo, ja hänet haudattiin Samariaan. Hänen poikansa Jooas tuli kuninkaaksi hänen jälkeensä.',
        10: 'Juudan kuninkaan Jooaan kolmantenakymmenentenä seitsemäntenä hallitusvuotena tuli Jooas, Jooahaan poika, Israelin kuninkaaksi. Hän hallitsi Samariassa kuusitoista vuotta.',
        11: 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä, vaan vaelsi niissä.',
        12: 'Mitä muuta on kerrottavaa Jooaasta, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän soti Juudan kuningasta Amasjaa vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        13: 'Jooas meni lepoon isiensä luo, ja Jerobeam istui hänen valtaistuimelleen. Jooas haudattiin Samariaan Israelin kuningasten viereen.',
        14: 'Kun Elisa oli sairastanut kuolintautiaan, Jooas, Israelin kuningas, oli tullut hänen luokseen. Kumartuneena hänen kasvojensa yli hän oli itkenyt ja sanonut: "Isäni, isäni! Israelin sotavaunut ja ratsumiehet!"',
        15: 'Elisa oli sanonut hänelle: "Nouda jousi ja nuolia." Hän oli noutanut hänelle jousen ja nuolia.',
        16: 'Sitten hän oli sanonut Israelin kuninkaalle: "Laske kätesi jouselle." Kun hän oli laskenut kätensä, Elisa pani kätensä kuninkaan kätten päälle.',
        17: 'Hän sanoi: "Avaa ikkuna itään päin." Kun tämä oli avannut sen, Elisa sanoi: "Ammu." Niin hän ampui. Hän sanoi: " Herran voitonnuoli, voitonnuoli Aramia vastaan! Sinä olet voittava aramilaiset Afekissa perin pohjin."',
        18: 'Ja hän sanoi: "Ota nuolet." Kun hän oli ne ottanut, hän sanoi Israelin kuninkaalle: "Tao [niitä] maahan." Niin hän löi kolme kertaa ja lakkasi sitten.',
        19: 'Mutta Jumalan mies vihastui häneen ja sanoi: "Sinun olisi pitänyt lyödä viisi tai kuusi kertaa: silloin olisit voittanut aramilaiset perin pohjin. Mutta nyt olet voittava aramilaiset ainoastaan kolme kertaa."',
        20: 'Elisa kuoli, ja hänet haudattiin. Mooabilaisten partiojoukkoja tuli maahan vuosi vuodelta.',
        21: 'Kerran, kun he haudatessaan erästä miestä näkivät partiojoukon, he heittivät miehen Elisan hautaan ja menivät matkoihinsa. Kun mies kosketti Elisan luita, hän virkosi ja nousi jaloilleen.',
        22: 'Hasael, Aramin kuningas, sorti Israelia, niin kauan kuin Jooahas eli.',
        23: 'Mutta Herra oli heille laupias, armahti heitä ja kääntyi heidän puoleensa liiton tähden, jonka hän oli tehnyt Aabrahamin, Iisakin ja Jaakobin kanssa. Sillä hän ei tahtonut tuhota heitä, eikä hän ollut vielä heittänyt heitä pois kasvojensa edestä.',
        24: 'Hasael, Aramin kuningas, kuoli, ja hänen poikansa Benhadad tuli kuninkaaksi hänen jälkeensä.',
        25: 'Jooas, Jooahaan poika, otti Benhadadilta, Hasaelin pojalta, takaisin ne kaupungit, jotka tämä oli asevoimin ottanut hänen isältään Jooahaalta. Kolme kertaa Jooas voitti hänet ja otti takaisin Israelin kaupungit.',
    },
    14: {
        1: 'Israelin kuninkaan Jooaan, Jooahaan pojan, toisena hallitusvuotena tuli Amasja, Jooaan poika, Juudan kuninkaaksi.',
        2: 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddin Jerusalemista.',
        3: 'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan niin kuin hänen isänsä Daavid. Kaikessa hän teki, niin kuin hänen isänsä Jooas oli tehnyt.',
        4: 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.',
        5: 'Kun kuninkuus oli vahvistunut hänen käsissään, hän surmautti ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.',
        6: 'Mutta murhaajien lapset hän jätti surmaamatta, kuten on kirjoitettu Mooseksen lain kirjaan, jossa Herra on käskenyt: "Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden. Kukin rangaistakoon kuolemalla oman syntinsä tähden."',
        7: 'Hän voitti edomilaiset Suolalaaksossa, kymmenentuhatta miestä, ja valloitti Seelan asevoimin ja antoi sille nimen Jokteel, joka sillä on tänäkin päivänä.',
        8: 'Silloin Amasja lähetti sanansaattajat Israelin kuninkaan Jooaan, Jooahaan pojan, Jeehun pojanpojan luo ja käski sanoa hänelle: "Tule, otelkaamme keskenämme."',
        9: 'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: "Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, sanan: \'Anna tyttäresi vaimoksi pojalleni.\' Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.',
        10: 'Sinä olet voittanut Edomin, ja siitä olet käynyt ylpeäksi. Tyydy siihen kunniaan ja pysy kotonasi. Minkä tähden tuotat onnettomuuden? Sinä kukistut itse ja Juuda kanssasi."',
        11: 'Mutta Amasja ei totellut. Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he, hän ja Amasja, Juudan kuningas, ottelivat keskenään Beet-Semeksessä, joka on Juudan aluetta.',
        12: 'Israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin teltalleen.',
        13: 'Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Ahasjan pojanpojan, Beet-Semeksessä vangiksi. Kun hän tuli Jerusalemiin, hän revitti Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.',
        14: 'Hän otti kaiken kullan ja hopean sekä kaiken esineistön, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli, sekä panttivankeja, ja palasi Samariaan.',
        15: 'Mitä muuta on kerrottavaa Jooaasta, siitä, mitä hän teki, ja hänen urotöistään, kuinka hän soti Amasjaa, Juudan kuningasta, vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        16: 'Jooas meni lepoon isiensä luo, ja hänet haudattiin Samariaan Israelin kuningasten viereen. Hänen poikansa Jerobeam tuli kuninkaaksi hänen jälkeensä.',
        17: 'Mutta Juudan kuningas Amasja, Jooaan poika, eli Israelin kuninkaan Jooaan, Jooahaan pojan, kuoleman jälkeen viisitoista vuotta.',
        18: 'Mitä muuta on kerrottavaa Amasjasta, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        19: 'Häntä vastaan tehtiin Jerusalemissa salaliitto. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja he surmasivat hänet siellä.',
        20: 'Hänet nostettiin hevosten selkään ja haudattiin Jerusalemiin isiensä viereen Daavidin kaupunkiin.',
        21: 'Mutta koko Juudan kansa otti Asarjan, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.',
        22: 'Hän linnoitti Eilatin ja palautti sen Juudalle, sitten kun kuningas oli mennyt lepoon isiensä luo.',
        23: 'Juudan kuninkaan Amasjan, Jooaan pojan, viidentenätoista hallitusvuotena tuli Jerobeam, Jooaan poika, Israelin kuninkaaksi ja hallitsi Samariassa neljäkymmentä yksi vuotta.',
        24: 'Hän teki sitä, mikä on pahaa Herran silmissä, hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        25: 'Hän palautti entiselleen Israelin alueen, siitä, mistä mennään Hamatiin, aina Aromaan mereen saakka, sen sanan mukaan, jonka Herra, Israelin Jumala, oli puhunut palvelijansa, profeetta Joonan, Amittain pojan, kautta, joka oli kotoisin Gat-Heeferistä.',
        26: 'Sillä Herra oli nähnyt Israelin hyvin katkeran kurjuuden, kuinka kaikki tyynni menehtyivät eikä Israelilla ollut auttajaa',
        27: 'Silloin Herra ei ollut vielä sanonut, että hän pyyhkii Israelin nimen pois taivaan alta, ja niin hän vapautti heidät Jerobeamin, Jooaan pojan, kautta.',
        28: 'Mitä muuta on kerrottavaa Jerobeamista, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän kävi sotaa ja kuinka hän palautti Israelille Damaskosta ja Hamatista sen, mikä oli ollut Juudan. Se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        29: 'Jerobeam meni lepoon isiensä, Israelin kuningasten, luo. Hänen poikansa Sakarja tuli kuninkaaksi hänen jälkeensä.',
    },
    15: {
        1: 'Jerobeamin, Israelin kuninkaan, kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Asarja, Amasjan poika, Juudan kuninkaaksi.',
        2: 'Hän oli kuudentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja Jerusalemista.',
        3: 'Hän teki sitä, mikä on oikein Herran silmissä, aivan kuten hänen isänsä Amasja oli tehnyt.',
        4: 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.',
        5: 'Herra löi kuningasta, niin että hän oli spitaalinen kuolinpäiväänsä saakka. Hän asui eri talossa, mutta Jootam, kuninkaan poika, oli linnan päällikkönä ja jakoi oikeutta maan kansalle.',
        6: 'Mitä muuta on kerrottavaa Asarjasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        7: 'Asarja meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen poikansa Jootam tuli kuninkaaksi hänen jälkeensä.',
        8: 'Asarjan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena tuli Sakarja, Jerobeamin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusi kuukautta.',
        9: 'Hän teki sitä, mikä on pahaa Herran silmissä, kuten hänen isänsäkin olivat tehneet. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        10: 'Sallum, Jaabeksen poika, teki salaliiton häntä vastaan ja löi hänet kuoliaaksi kansan nähden ja tuli kuninkaaksi hänen jälkeensä.',
        11: 'Mitä muuta on kerrottavaa Sakarjasta, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        12: 'Näin toteutui Herran sana, jonka hän oli puhunut Jeehulle sanoen: "Sinun poikasi istukoot Israelin valtaistuimella neljänteen polveen". Niin tapahtui.',
        13: 'Sallum, Jaabeksen poika, tuli kuninkaaksi Ussian, Juudan kuninkaan, kolmantenakymmenentenä yhdeksäntenä hallitusvuotena, ja hän hallitsi Samariassa kuukauden päivät.',
        14: 'Mutta silloin Menahem, Gaadin poika, lähti liikkeelle Tirsasta, tuli Samariaan ja löi Sallumin, Jaabeksen pojan, kuoliaaksi Samariassa. Hän tuli kuninkaaksi tämän jälkeen.',
        15: 'Mitä muuta on kerrottavaa Sallumista ja salaliitosta, jonka hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        16: 'Siihen aikaan Menahem hävitti Tifsahin ja kaiken, mitä siellä oli, niin myös sen alueen Tirsasta lähtien, koska he eivät avanneet hänelle portteja. Hän hävitti sen ja halkaisi kaikki raskaana olevat vaimot.',
        17: 'Juudan kuninkaan Asarjan kolmantenakymmenentenä yhdeksäntenä hallitusvuotena tuli Menahem, Gaadin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kymmenen vuotta.',
        18: 'Hän teki sitä, mikä on pahaa Herran edessä. Hän ei luopunut koko elinaikanaan mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        19: 'Puul, Assurin kuningas, hyökkäsi maahan, ja Menahem antoi Puulille tuhat talenttia hopeaa, että tämä auttaisi häntä ja vahvistaisi kuninkuuden hänen käsiinsä.',
        20: 'Menahem otti rahat verona Israelilta, kaikilta varakkailta miehiltä, niin että jokainen joutui maksamaan Assurin kuninkaalle viisikymmentä sekeliä hopeaa.',
        21: 'Assurin kuningas palasi takaisin eikä jäänyt maahan. Mitä muuta on kerrottavaa Menahemista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        22: 'Menahem meni lepoon isiensä luo. Hänen poikansa Pekahja tuli kuninkaaksi hänen jälkeensä.',
        23: 'Juudan kuninkaan Asarjan viidentenäkymmenentenä hallitusvuotena tuli Pekahja, Menahemin poika, Israelin kuninkaaksi ja hallitsi Samariassa kaksi vuotta.',
        24: 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        25: 'Pekah, Remaljan poika, hänen vaunusoturinsa, teki salaliiton häntä vastaan ja tappoi hänet Samariassa kuninkaan linnan palatsissa, sekä hänet että Argobin ja Arjen, jolloin Pekahilla oli mukanaan viisikymmentä Gileadin miestä. Hän surmasi hänet ja tuli kuninkaaksi hänen jälkeensä.',
        26: 'Mitä muuta on kerrottavaa Pekahjasta ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        27: 'Juudan kuninkaan Asarjan viidentenäkymmenentenä toisena hallitusvuotena tuli Pekah, Remaljan poika, Israelin kuninkaaksi ja hallitsi Samariassa kaksikymmentä vuotta.',
        28: 'Hän teki sitä, mikä on pahaa Herran silmissä. Hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.',
        29: 'Israelin kuninkaan Pekahin aikana tuli Tiglat-Pileser, Assurin kuningas, ja valloitti Iijonin, Aabel-Beet-Maakan, Jaanoahin, Kedeksen, Haasorin, Gileadin ja Galilean, koko Naftalin maan, ja vei asukkaat karkotukseen Assuriin.',
        30: 'Mutta Hoosea, Eelan poika, teki salaliiton Pekahia, Remaljan poikaa, vastaan ja löi hänet kuoliaaksi ja tuli kuninkaaksi hänen jälkeensä Jootamin, Ussian pojan, kahdentenakymmenentenä hallitusvuotena.',
        31: 'Mitä muuta on kerrottavaa Pekahista ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.',
        32: 'Israelin kuninkaan Pekahin, Remaljan pojan, toisena hallitusvuotena tuli Jootam, Juudan kuninkaan Ussian poika, kuninkaaksi.',
        33: 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä oli nimeltään Jerusa Saadokin tytär.',
        34: 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niin kuin hänen isänsä Ussia oli tehnyt.',
        35: 'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla. Hän rakennutti Yläportin Herran temppeliin.',
        36: 'Mitä muuta on kerrottavaa Jootamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        37: 'Niihin aikoihin alkoivat Resin, Aramin kuningas, ja Pekah, Remaljan poika, Herran lähettäminä käydä Juudan kimppuun.',
        38: 'Jootam meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen, isänsä Daavidin kaupunkiin. Hänen poikansa Aahas tuli kuninkaaksi hänen jälkeensä.',
    },
    16: {
        1: 'Pekahin, Remaljan pojan, seitsemäntenätoista hallitusvuotena tuli Aahas, Juudan kuninkaan Jootamin poika, kuninkaaksi.',
        2: 'Aahas oli kahdenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä oli oikein Herran, hänen Jumalansa, silmissä, kuten hänen isänsä Daavid,',
        3: 'vaan vaelsi Israelin kuningasten tietä. Jopa hän pani poikansakin kulkemaan tulen läpi, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.',
        4: 'Hän uhrasi ja suitsutti uhrikukkuloilla ja kummuilla ja jokaisen vihreän puun alla.',
        5: 'Siihen aikaan Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, lähtivät sotimaan Jerusalemia vastaan. He saartoivat Aahaan, mutta eivät voineet valloittaa kaupunkia.',
        6: 'Samaan aikaan Resin, Aramin kuningas, palautti Eilatin Aramille ja karkotti Juudan miehet Eilatista. Niin tulivat aramilaiset Eilatiin ja asettuivat sinne, ja siellä heitä on tänäkin päivänä.',
        7: 'Mutta Aahas lähetti sanansaattajat Assurin kuninkaan Tiglat-Pileserin luo ja käski sanoa hänelle: "Minä olen palvelijasi ja poikasi. Tule ja pelasta minut Aramin kuninkaan ja Israelin kuninkaan käsistä. He ovat hyökänneet kimppuuni."',
        8: 'Aahas otti hopean ja kullan, mitä Herran temppelissä ja kuninkaan palatsin aarrekammioissa oli, ja lähetti sen lahjaksi Assurin kuninkaalle.',
        9: 'Assurin kuningas kuuli häntä. Assurin kuningas lähti Damaskoa vastaan, valloitti sen, ja vei asukkaat karkotukseen Kiiriin ja surmasi Resinin.',
        10: 'Kuningas Aahas lähti Damaskoon kohtaamaan Assurin kuningasta Tiglat-Pileseriä. Kun kuningas Aahas näki Damaskossa olevan alttarin, hän lähetti pappi Uurialle kuvan alttarista ja sen mukaan tehdyn tarkan mallin.',
        11: 'Pappi Uuria rakensi alttarin aivan sen määräyksen mukaan, jonka kuningas Aahas oli hänelle lähettänyt Damaskosta. Aivan sen mukaan pappi Uuria teki, jo ennen kuin kuningas Aahas oli palannut Damaskosta.',
        12: 'Kun kuningas palasi Damaskosta ja näki alttarin, hän astui alttarin luo ja nousi sen päälle,',
        13: 'poltti polttouhrinsa ja ruokauhrinsa, vuodatti juomauhrinsa ja vihmoi uhraamansa uhrin veren alttarille.',
        14: 'Mutta vaskialttarin, joka oli Herran edessä, hän siirsi pois temppelin edustalta, alttarin ja Herran temppelin väliltä, ja pani sen alttarin pohjoissivulle.',
        15: 'Kuningas Aahas käski pappi Uuriaa ja sanoi: "Polta suuremmalla alttarilla aamun polttouhri ja ehtoon ruokauhri ja kuninkaan polttouhri sekä hänen ruokauhrinsa, niin myös koko maan kansan polttouhri sekä heidän ruoka- ja juomauhrinsa, ja vihmo kaikki sekä polttouhrin että teurasuhrin veri sen päälle. Mutta vaskialttarin käyttämistä minä vielä mietin."',
        16: 'Pappi Uuria teki kaiken, mitä kuningas Aahas oli käskenyt.',
        17: 'Kuningas Aahas leikkautti irti telineiden kehäpienat ja otti altaat pois niiden päältä. Mutta meren hän nostatti pois vaskinautojen päältä, jotka olivat sen alla, ja panetti sen kivialustalle.',
        18: 'Katetun sapattikäytävän, joka oli rakennettu temppeliin, ja kuninkaan ulkopuolisen sisäänkäynnin hän muutti Herran temppelin sisään Assurin kuninkaan vuoksi.',
        19: 'Mitä muuta on vielä kerrottavaa Aahaasta, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        20: 'Aahas meni lepoon isiensä luo, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Sitten hänen poikansa Hiskia tuli kuninkaaksi hänen jälkeensä.',
    },
    17: {
        1: 'Juudan kuninkaan Aahaan kahdentenatoista hallitusvuotena tuli Hoosea, Eelan poika, Israelin kuninkaaksi Samariaan ja hallitsi yhdeksän vuotta.',
        2: 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niin kuin ne Israelin kuninkaat, jotka olivat olleet ennen häntä.',
        3: 'Hänen kimppuunsa hyökkäsi Salmaneser, Assurin kuningas, ja Hoosea tuli hänen palvelijakseen ja maksoi hänelle veroa.',
        4: 'Mutta Assurin kuningas huomasi Hoosean olevan salahankkeissa, koska tämä lähetti sanansaattajat Soon, Egyptin kuninkaan, luo eikä suorittanut enää kuten ennen vuotuista veroa Assurin kuninkaalle. Niin Assurin kuningas vangitutti hänet ja piti häntä sidottuna vankilassa.',
        5: 'Assurin kuningas hyökkäsi koko maan kimppuun ja meni Samariaan ja piiritti sitä kolme vuotta.',
        6: 'Hoosean yhdeksäntenä hallitusvuotena Assurin kuningas valloitti Samarian ja vei Israelin karkotukseen Assuriin ja asetti heidät asumaan Halahiin ja Haaborin, Goosanin joen, rannoille sekä Meedian kaupunkeihin.',
        7: 'Näin tapahtui, koska israelilaiset olivat tehneet syntiä Herraa, Jumalaansa, vastaan, joka oli johdattanut heidät Egyptin maasta, pois faraon, Egyptin kuninkaan, käsistä, ja koska he olivat pelänneet muita jumalia.',
        8: 'He olivat myös vaeltaneet niiden kansojen säädösten mukaan, jotka Herra oli karkottanut israelilaisten tieltä, ja tehneet sitä, mitä Israelin kuninkaatkin.',
        9: 'Israelilaiset olivat tehneet Herraa, Jumalaansa, vastaan sellaista, mikä ei ole oikein: he olivat rakentaneet itselleen uhrikukkuloita kaikkiin kaupunkeihinsa, sekä vartiotornien luo että varustettuihin kaupunkeihin.',
        10: 'He olivat pystyttäneet itselleen patsaita ja aserapaaluja jokaiselle korkealle kummulle ja jokaisen vihreän puun alle.',
        11: 'He olivat polttaneet uhreja kaikilla uhrikukkuloilla, kuten ne kansat, jotka Herra oli karkottanut heidän tieltään. He olivat harjoittaneet pahuutta ja vihoittaneet Herran.',
        12: 'He olivat palvelleet epäjumalia, vaikka Herra oli heille sanonut: "Älkää tehkö sitä."',
        13: 'Herra oli varoittanut sekä Israelia että Juudaa kaikkien profeettojensa, kaikkien näkijöiden, kautta ja sanonut: "Palatkaa pahoilta teiltänne ja noudattakaa käskyjäni ja säädöksiäni, kaiken sen lain mukaan, jonka minä säädin isillenne ja jonka olen teille ilmoittanut palvelijoitteni, profeettojen, kautta."',
        14: 'Mutta he eivät kuulleet, vaan olivat niskureita niin kuin heidän isänsäkin, jotka eivät uskoneet Herraan, Jumalaansa.',
        15: 'He olivat hylänneet hänen käskynsä ja hänen liittonsa, jonka hän oli tehnyt heidän isiensä kanssa, ja todistukset, jotka hän oli heille antanut. He olivat seuranneet turhia jumalia, ja tulleet turhanaikaisiksi, kun seurasivat pakanakansoja, jotka asuivat heidän ympärillään, vaikka Herra oli kieltänyt heitä tekemästä niin kuin ne.',
        16: 'He olivat hylänneet Herran, Jumalansa, kaikki käskyt ja tehneet itselleen valettuja kuvia, kaksi vasikkaa. He olivat tehneet itselleen myös aserapaaluja ja kumarsivat kaikkea taivaan joukkoa ja palvelivat Baalia.',
        17: 'He panivat poikansa ja tyttärensä kulkemaan tulen läpi ja tekivät taikoja ja harjoittivat noituutta. He myivät itsensä tekemään sitä, mikä on pahaa Herran silmissä, ja vihoittivat hänet.',
        18: 'Herra vihastui suuresti Israeliin ja poisti heidät kasvojensa edestä, ettei jäänyt jäljelle muuta kuin yksin Juudan sukukunta.',
        19: 'Juudakaan ei pitänyt Herran, Jumalansa, käskyjä, vaan he vaelsivat niiden säädösten mukaan, jotka Israel itse oli tehnyt.',
        20: 'Herra hylkäsi koko Israelin heimon, nöyryytti heitä ja antoi heidät ryöstäjien käsiin ja heitti viimein heidät pois kasvojensa edestä.',
        21: 'Sillä kun hän oli reväissyt Israelin Daavidin suvulta ja he olivat tehneet kuninkaaksi Jerobeamin, Nebatin pojan, Jerobeam oli kääntänyt Israelin pois Herrasta ja saattanut heidät tekemään suuren synnin.',
        22: 'Israelilaiset vaelsivat kaikissa synneissä, joita Jerobeam oli tehnyt, eivätkä luopuneet niistä.',
        23: 'Herra poisti lopulta Israelin kasvojensa edestä, niin kuin hän oli puhunut kaikkien palvelijoidensa, profeettojen, kautta. Israel vietiin pois maastaan karkotukseen Assuriin, jossa he ovat tänäkin päivänä.',
        24: 'Sen jälkeen Assurin kuningas antoi tuoda kansaa Baabelista, Kuutasta, Avvasta, Hamatista ja Sefarvaimista ja asetti heidät asumaan Samarian kaupunkeihin israelilaisten sijaan. He ottivat Samarian omakseen ja asettuivat sen kaupunkeihin.',
        25: 'Kun he siellä olonsa ensi aikoina eivät pelänneet Herraa, lähetti Herra heidän keskuuteensa leijonia, jotka tappoivat heitä.',
        26: 'Se kerrottiin Assurin kuninkaalle sanoen: "Kansat, jotka veit karkotukseen ja asetit asumaan Samarian kaupunkeihin, eivät tiedä, millä tavalla sen maan Jumalaa on palveltava. Sen tähden hän on lähettänyt leijonia heidän keskuuteensa, ja katso, ne surmaavat heitä, koska he eivät tiedä, millä tavalla sen maan Jumalaa on palveltava."',
        27: 'Silloin Assurin kuningas käski sanoen: "Viekää sinne joku niistä papeista, jotka toitte sieltä karkotukseen. Joku heistä menköön sinne ja asukoon siellä ja opettakoon heille, millä tavalla maan Jumalaa on palveltava."',
        28: 'Niin eräs niistä papeista, jotka he olivat vieneet Samariasta karkotukseen, tuli ja asettui Beeteliin. Hän opetti heille, kuinka heidän oli pelättävä Herraa.',
        29: 'Mutta jokainen kansa teki itselleen omat jumalansa, ja he panivat ne samarialaisten rakentamiin uhrikukkulatemppeleihin, jokainen kansa niissä kaupungeissa, joissa se asui.',
        30: 'Baabelin miehet tekivät itselleen Sukkot-Benotin, Kuutin miehet tekivät Neergalin, Hamatin miehet Asiman,',
        31: 'avvalaiset tekivät Nibhaan ja Tartakin, sefarvaimilaiset polttivat poikiaan tulessa Adrammelekille ja Annammelekille, Sefarvaimin jumalille.',
        32: 'Mutta he pelkäsivät myös Herraa. He asettivat itselleen uhrikukkulapappeja omasta keskuudestaan, ja nämä uhrasivat heidän puolestaan uhrikukkulatemppeleissä.',
        33: 'He pelkäsivät tosin Herraa, mutta palvelivat myös omia jumaliaan samalla tavalla kuin ne kansat, joiden keskuudesta heidät oli tuotu.',
        34: 'Vielä tänäkin päivänä he tekevät vanhan tapansa mukaan: he eivät pelkää Herraa eivätkä tee saamiensa säädösten ja oikeuksien mukaan, eivät sen lain ja niiden käskyjen mukaan, jotka Herra on antanut Jaakobin pojille, hänen, jolle hän antoi nimen Israel.',
        35: 'Herra oli tehnyt liiton näiden kanssa ja käskenyt heitä sanoen: "Älkää pelätkö muita jumalia, älkää kumartako ja palvelko niitä älkääkä uhratko niille,',
        36: 'vaan [pelätkää] Herraa, joka johdatti teidät Egyptin maasta suurella voimalla ja ojennetulla käsivarrella, häntä te pelätkää, häntä kumartakaa ja hänelle uhratkaa.',
        37: 'Niitä säädöksiä ja oikeuksia, sitä lakia ja niitä käskyjä, jotka hän on teille kirjoittanut, noudattakaa alati tarkoin, mutta älkää pelätkö muita jumalia.',
        38: 'Liittoa, jonka tein kanssanne, älkää unohtako. Älkääkä pelätkö muita jumalia,',
        39: 'vaan pelätkää ainoastaan Herraa, Jumalaanne, niin hän pelastaa teidät kaikkien vihollistenne käsistä."',
        40: 'Mutta he eivät totelleet, vaan tekivät vanhan tapansa mukaan.',
        41: 'Nämä kansat pelkäsivät Herraa, mutta palvelivat samalla omia jumalankuviaan. Myös heidän lapsensa ja heidän lastensa lapset tekevät vielä tänä päivänä samoin, kuin heidän isänsä ovat tehneet.',
    },
    18: {
        1: 'Israelin kuninkaan Hoosean, Eelan pojan, kolmantena hallitusvuotena tuli Hiskia, Juudan kuninkaan Aahaan poika, kuninkaaksi.',
        2: 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abi, Sakarjan tytär.',
        3: 'Hän teki sitä, mikä on oikein Herran silmissä, aivan kuin hänen isänsä Daavid oli tehnyt.',
        4: 'Hän poisti uhrikukkulat, murskasi patsaat, hakkasi maahan aserapaalun ja löi palasiksi vaskikäärmeen, jonka Mooses oli tehnyt. Sillä niihin aikoihin asti israelilaiset olivat polttaneet uhreja sille. Sitä kutsuttiin nimellä Nehustan.',
        5: 'Hän turvasi Herraan, Israelin Jumalaan, niin ettei kukaan ollut hänen kaltaisensa kaikista hänen jälkeensä tulleista Juudan kuninkaista eikä niistä, jotka olivat olleet ennen häntä.',
        6: 'Hän riippui kiinni Herrassa eikä luopunut hänestä, vaan noudatti hänen käskyjään, jotka Herra oli antanut Moosekselle.',
        7: 'Herra oli hänen kanssaan. Hän menestyi kaikessa, mihin ryhtyi. Hän kapinoi Assurin kuningasta vastaan eikä enää palvellut häntä.',
        8: 'Hän voitti filistealaiset ja valtasi heidän alueensa aina Gassaan asti, sekä vartiotornit että varustetut kaupungit.',
        9: 'Mutta kuningas Hiskian neljäntenä hallitusvuotena, joka oli Israelin kuninkaan Hoosean, Eelan pojan, seitsemäs hallitusvuosi, hyökkäsi Salmaneser, Assurin kuningas, Samarian kimppuun ja piiritti sitä.',
        10: 'Hän valloitti sen kolmen vuoden kuluttua. Hiskian kuudentena hallitusvuotena, joka oli Israelin kuninkaan Hoosean yhdeksäs hallitusvuosi, valloitettiin Samaria.',
        11: 'Assurin kuningas vei Israelin karkotukseen Assuriin ja sijoitti heidät Halahiin ja Haaborin, Goosanin joen, rannoille ja Meedian kaupunkeihin,',
        12: 'sen tähden että he eivät olleet kuulleet Herran, Jumalansa, ääntä, vaan olivat rikkoneet hänen liittonsa, kaiken, mitä Mooses, Herran palvelija, oli käskenyt. He eivät olleet kuulleet sitä eivätkä tehneet sen mukaan.',
        13: 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.',
        14: 'Hiskia, Juudan kuningas, lähetti Assurin kuninkaalle Laakiiseen sanan: "Olen rikkonut, käänny pois kimpustani. Kannan, mitä panet kannettavakseni." Assurin kuningas määräsi Hiskian, Juudan kuninkaan, maksettavaksi kolmesataa talenttia hopeaa ja kolmekymmentä talenttia kultaa.',
        15: 'Hiskia antoi kaikki rahat, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli.',
        16: 'Siihen aikaan Hiskia leikkautti irti Herran temppelin ovista ja pihtipielistä sen päällystyksen, jolla Hiskia, Juudan kuningas, oli ne päällystänyt, ja antoi sen Assurin kuninkaalle.',
        17: 'Mutta Assurin kuningas lähetti Laakiista Tartanin ja ylimmäisen hoviherran ja Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin. Nämä lähtivät liikkeelle ja tulivat Jerusalemiin, ja lähdettyään liikkeelle ja tultuaan he pysähtyivät Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.',
        18: 'Kun he sitten kutsuivat kuningasta, menivät Eljakim, Hilkian poika, joka oli linnan päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, heidän luokseen.',
        19: 'Rabsake sanoi heille: "Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, mikä sinulla on?',
        20: 'Arvelet kai, että pelkästä huulten puheesta tulee neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?',
        21: 'Katso, sinä luotat nyt Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.',
        22: "Vai sanotteko te ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava, täällä Jerusalemissa?'",
        23: 'Mutta lyö nyt vetoa herrani, Assurin kuninkaan, kanssa: annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.',
        24: 'Kuinka torjut ainoankaan käskynhaltijan, ainoankaan herrani vähimmän palvelijan, hyökkäyksen? Luotat Egyptiin, sen vaunuihin ja ratsumiehiin.',
        25: 'Olenko minä siis Herran sallimatta hyökännyt tämän paikan kimppuun hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se.\'"',
        26: 'Eljakim, Hilkian poika, ja Sebna ja Jooah sanoivat Rabsakelle: "Puhu palvelijoillesi aramin kieltä, sillä me ymmärrämme sitä. Älä puhu kanssamme juudan kieltä kansan kuullen, jota on muurilla."',
        27: 'Mutta Rabsake vastasi heille: "Onko herrani lähettänyt minut puhumaan näitä sanoja herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla syödäkseen kanssanne omaa ulostettaan ja juodakseen omaa virtsaansa?"',
        28: 'Rabsake astui esiin, huusi kovalla äänellä juudan kielellä, puhui ja sanoi: "Kuulkaa suurkuninkaan, Assurin kuninkaan, sana.',
        29: "Näin sanoo kuningas: 'Älkää antako Hiskian pettää itseänne, sillä hän ei voi pelastaa teitä käsistäni.",
        30: 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät, eikä tätä kaupunkia anneta Assurin kuninkaan käsiin.',
        31: "Älkää kuulko Hiskiaa.' Sillä Assurin kuningas sanoo näin: 'Tehkää sovinto kanssani ja antautukaa minulle, niin saatte syödä kukin omasta viinipuustanne ja viikunapuustanne ja juoda kukin omasta kaivostanne,",
        32: 'kunnes tulen ja vien teidät maahan, joka on maanne kaltainen, vilja-, viini- ja leipämaahan, viinitarhojen, jalon öljypuun ja hunajan maahan. Niin elätte ettekä kuole. Mutta älkää kuulko Hiskiaa, sillä hän viettelee teidät sanoessaan: Herra pelastaa meidät.',
        33: 'Onko muidenkaan kansojen jumalista yksikään pelastanut maatansa Assurin kuninkaan käsistä?',
        34: 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin, Heenan ja Ivvan jumalat? Ovatko ne pelastaneet Samariaa käsistäni?',
        35: 'Onko muiden maiden kaikista jumalista ainoakaan pelastanut maatansa käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin käsistäni?\'"',
        36: 'Mutta kansa oli vaiti, eivätkä he vastanneet hänelle mitään. Sillä kuningas oli käskenyt niin ja sanonut: "Älkää vastatko hänelle."',
        37: 'Palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.',
    },
    19: {
        1: 'Kun kuningas Hiskia kuuli sen, hän repäisi vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.',
        2: 'Hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat säkkeihin puettuina profeetta Jesajan, Aamosin pojan, luo.',
        3: 'He sanoivat hänelle: "Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.',
        4: 'Ehkä Herra, Jumalasi, kuulee kaikki Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, Jumalasi, on kuullut. Kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'"',
        5: 'Kun kuningas Hiskian palvelijat tulivat Jesajan luo,',
        6: 'Jesaja sanoi heille: "Sanokaa näin herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan nuorukaiset ovat häväisseet minua.',
        7: 'Katso, [minä] annan sellaisen hengen mennä häneen, että hän kuultuaan sanoman palaa omaan maahansa. Annan hänen kaatua miekkaan omassa maassaan.\'"',
        8: 'Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan, sillä hän oli kuullut, että tämä oli lähtenyt pois Laakiista.',
        9: 'Mutta kun Sanherib kuuli sanottavan Tirhakasta, Kuusin kuninkaasta: "Katso, hän on lähtenyt liikkeelle sotiakseen sinua vastaan", hän lähetti taas sanansaattajat Hiskian luo ja käski sanoa:',
        10: '"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.',
        11: 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Mutta sinäkö pelastuisit!',
        12: 'Ovatko kansojen jumalat pelastaneet niitä, jotka isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?',
        13: 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'"',
        14: 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, hän meni Herran temppeliin, ja Hiskia levitti sen Herran eteen.',
        15: 'Hiskia rukoili Herran edessä ja sanoi: " Herra, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntien Jumala, sinä olet tehnyt taivaan ja maan.',
        16: 'Herra, kallista korvasi ja kuule, Herra, avaa silmäsi ja katso. Kuule Sanheribin sanat, kuinka hän lähetti tuon miehen herjaamaan elävää Jumalaa.',
        17: 'On totta, Herra, että Assurin kuninkaat ovat hävittäneet kansat ja heidän maansa.',
        18: 'He ovat heittäneet heidän jumalansa tuleen, sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sen tähden he saattoivat hävittää ne.',
        19: 'Mutta pelasta nyt meidät, Herra, Jumalamme, hänen käsistään, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, yksin olet Jumala."',
        20: 'Jesaja, Aamosin poika, lähetti Hiskialle tämän sanan: "Näin sanoo Herra, Israelin Jumala: Mitä olet minulta Sanheribin, Assurin kuninkaan, tähden rukoillut, sen olen kuullut.',
        21: 'Tämä on sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua, tytär Jerusalem nyökyttää ilkkuen päätään jälkeesi.',
        22: 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.',
        23: "Sanansaattajiesi kautta herjasit Herraa ja sanoit: 'Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin asti. Hakkasin maahan sen korkeat setrit, sen parhaat sypressit, ja tunkeuduin sen etäisimpään yöpymispaikkaan, sen rehevimpään metsään.",
        24: "Minä kaivoin kaivoja ja join kuiviin muukalaisten vedet, ja jalkapohjallani kuivasin kaikki Egyptin virrat.'",
        25: 'Etkö ole kuullut: kauan sitten olen tämän valmistanut, muinaisuudesta asti tämän ajatellut! Nyt olen sen toteuttanut, että hävittäisit varustetut kaupungit autioiksi kivikasoiksi.',
        26: 'Niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään. Heidän kävi kuin kedon ruohon, kuin vihannan heinän, kuin katolla kasvavien kortten ja kuin laihon, joka kuivettuu ennen tuleentumistaan.',
        27: 'Istuitpa tai lähdit tai tulit, sen tiedän ja sen, että raivoat minua vastaan.',
        28: 'Koska raivoat minua vastaan ja koska ylpeytesi on tullut korviini, panen koukkuni nenääsi ja suitseni suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.',
        29: 'Tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesannon odelmaa, mutta kolmantena vuonna kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.',
        30: 'Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.',
        31: 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran kiivaus on sen tekevä.',
        32: 'Sen tähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä ammu siihen nuolta. Hän ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.',
        33: 'Samaa tietä, jota hän tuli, hän palaa, mutta tähän kaupunkiin hän ei tule, sanoo Herra.',
        34: 'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden."',
        35: 'Sinä yönä Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, katso, he olivat kaikki kuolleina ruumiina.',
        36: 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois. Hän palasi takaisin ja jäi Niiniveen.',
        37: 'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat Adrammelek ja Sareser hänet miekalla. Sitten he pakenivat Araratin maahan. Hänen poikansa Eesarhaddon tuli kuninkaaksi hänen jälkeensä.',
    },
    20: {
        1: 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan. Silloin profeetta Jesaja, Aamosin poika, tuli hänen luokseen ja sanoi hänelle: "Näin sanoo Herra: Järjestä asiasi, sillä sinä kuolet etkä enää parane."',
        2: 'Hän käänsi kasvonsa seinään päin ja rukoili Herraa sanoen:',
        3: '"Oi Herra, muista, kuinka olen vaeltanut edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää silmissäsi!" Hiskia itki katkerasti.',
        4: 'Mutta Jesaja ei ollut vielä lähtenyt keskimmäiseltä esipihalta, kun hänelle tuli tämä Herran sana:',
        5: '"Palaa takaisin ja sano Hiskialle, kansani ruhtinaalle: \'Näin sanoo Herra, isäsi Daavidin Jumala: Olen kuullut rukouksesi, olen nähnyt kyyneleesi. Katso, olen parantava sinut: jo kolmantena päivänä menet Herran temppeliin.',
        6: 'Lisään sinulle ikää viisitoista vuotta. Pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä. Varjelen tätä kaupunkia itseni tähden ja palvelijani Daavidin tähden.\'"',
        7: 'Jesaja sanoi: "Toimittakaa tänne viikunakakkua." Niin he toivat sitä ja panivat sitä paiseen päälle, ja hän parani.',
        8: 'Hiskia oli sanonut Jesajalle: "Mikä on merkkinä siitä, että Herra on parantava minut, niin että kolmantena päivänä voin mennä Herran temppeliin?"',
        9: 'Jesaja sanoi: "Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä hän on sanonut: varjo kulkee kymmenen astetta eteenpäin tai siirtyy kymmenen astetta takaisin."',
        10: 'Hiskia sanoi: "Varjon on helppo edetä kymmenen astetta. Ei, vaan siirtyköön varjo takaisin kymmenen astetta."',
        11: 'Profeetta Jesaja huusi Herraa, ja hän antoi varjon Aahaan aurinkokellossa siirtyä takaisin kymmenen astetta, jotka se oli jo laskeutunut.',
        12: 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, sillä hän oli kuullut, että Hiskia oli ollut sairaana.',
        13: 'Kuultuaan heitä Hiskia näytti heille koko varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissaan oli. Hiskian talossa ja koko hänen valtakunnassaan ei ollut mitään, mitä hän ei olisi heille näyttänyt.',
        14: 'Mutta profeetta Jesaja tuli kuningas Hiskian luo ja sanoi hänelle: "Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet luoksesi?" Hiskia vastasi: "He ovat tulleet kaukaisesta maasta, Baabelista."',
        15: 'Hän sanoi: "Mitä he ovat nähneet talossasi?" Hiskia vastasi: "Kaiken, mitä talossani on, he ovat nähneet. Aarrekammioissani ei ole mitään, mitä en olisi heille näyttänyt."',
        16: 'Jesaja sanoi Hiskialle: "Kuule Herran sana:',
        17: 'Katso, päivät tulevat, jolloin kaikki, mitä talossasi on ja mitä isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin, eikä mitään jää jäljelle, sanoo Herra.',
        18: 'Omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin."',
        19: 'Hiskia sanoi Jesajalle: " Herran sana, jonka olet puhunut, on hyvä." Sillä hän ajatteli: "Onpahan rauha ja turvallisuus minun päivinäni."',
        20: 'Mitä muuta on kerrottavaa Hiskiasta ja kaikista hänen urotöistään, sekä se, kuinka hän rakensi lammikon ja vesijohdon ja johti veden kaupunkiin, on kirjoitettuna Juudan kuningasten aikakirjassa.',
        21: 'Hiskia meni lepoon isiensä luo, ja hänen poikansa Manasse tuli kuninkaaksi hänen jälkeensä.',
    },
    21: {
        1: 'Manasse oli kahdentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Hefsibah.',
        2: 'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansojen kauhistavien tekojen mukaan, jotka Herra oli karkottanut israelilaisten tieltä.',
        3: 'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli hävittänyt, ja pystytti alttareita Baalille ja teki aseran, niin kuin Israelin kuningas Ahab oli tehnyt, kumarsi ja palveli kaikkea taivaan joukkoa.',
        4: 'Hän rakensi alttareita myös Herran temppeliin, josta paikasta Herra oli sanonut: "Jerusalemiin asetan nimeni."',
        5: 'Hän rakensi alttareita kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.',
        6: 'Hän pani myös poikansa kulkemaan tulen läpi, ennusteli merkeistä, harjoitti noituutta ja hankki itselleen vainaja- ja tietäjähenkien manaajia. Hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.',
        7: 'Teettämänsä Aseran kuvan hän asetti temppeliin, josta Herra oli sanonut Daavidille ja hänen pojalleen Salomolle: "Tähän temppeliin ja Jerusalemiin, jonka olen valinnut kaikista Israelin sukukunnista, asetan nimeni ikiajoiksi.',
        8: 'Enkä anna enää Israelin jalkojen harhailla pois siitä maasta, jonka olen antanut heidän isilleen, jos he vain kaikessa noudattavat sitä, mitä olen käskenyt heidän noudattaa – koko sitä lakia, jonka palvelijani Mooses on heille antanut."',
        9: 'Mutta he eivät totelleet, ja Manasse eksytti heidät tekemään pahaa enemmän kuin ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.',
        10: 'Herra puhui palvelijoidensa, profeettojen, kautta ja sanoi:',
        11: '"Koska Manasse, Juudan kuningas, on tehnyt nämä kauhistavat teot ja siten tehnyt pahaa enemmän kuin amorilaiset, jotka olivat ennen häntä, ja on saattanut epäjumalillaan myös Juudan tekemään syntiä,',
        12: 'sen tähden sanoo Herra, Israelin Jumala, näin: Katso, annan sellaisen onnettomuuden kohdata Jerusalemia ja Juudaa, että joka sen kuulee, sen molemmat korvat soivat.',
        13: "Mittaan Jerusalemin samalla mittanuoralla kuin Samarian ja punnitsen sen samalla vaa'alla kuin Ahabin suvun. Huuhdon Jerusalemin, niin kuin vati huuhdotaan: se huuhdotaan ja käännetään kumolleen.",
        14: 'Hylkään perintöosani jäännöksen ja annan heidät vihollistensa käsiin, niin että he joutuvat kaikkien vihollistensa saaliiksi ja ryöstettäviksi,',
        15: 'koska ovat tehneet sitä, mikä on pahaa silmissäni, ja vihoittaneet minut siitä päivästä lähtien, jona heidän isänsä lähtivät Egyptin maasta, tähän päivään asti."',
        16: 'Manasse vuodatti myös sangen paljon viatonta verta, niin että hän täytti sillä Jerusalemin ääriään myöten sen syntinsä lisäksi, jolla hän saattoi Juudan tekemään syntiä, tekemään sitä, mikä on pahaa Herran silmissä.',
        17: 'Mitä muuta on kerrottavaa Manassesta ja kaikesta, mitä hän teki, ja synnistä, minkä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        18: 'Manasse meni lepoon isiensä luo, ja hänet haudattiin linnansa puutarhaan, Ussan puutarhaan. Hänen poikansa Aamon tuli kuninkaaksi hänen jälkeensä.',
        19: 'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kaksi vuotta. Hänen äitinsä oli nimeltään Mesullemet, Haaruksen tytär, Jotbasta.',
        20: 'Hän teki sitä, mikä on pahaa Herran silmissä, niin kuin hänen isänsä Manasse oli tehnyt.',
        21: 'Hän vaelsi kaikessa samaa tietä, mitä hänen isänsä oli vaeltanut: hän palveli niitä epäjumalia, joita hänen isänsä oli palvellut, ja kumarsi niitä.',
        22: 'Hän hylkäsi Herran, isiensä Jumalan, eikä vaeltanut Herran tietä.',
        23: 'Aamonin palvelijat tekivät salaliiton häntä vastaan ja tappoivat kuninkaan hänen linnassaan.',
        24: 'Mutta maan kansa surmasi kaikki, jotka olivat tehneet salaliiton kuningas Aamonia vastaan. Maan kansa teki hänen poikansa Joosian kuninkaaksi hänen jälkeensä.',
        25: 'Mitä muuta on kerrottavaa Aamonista, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.',
        26: 'Hänet haudattiin omaan hautaansa Ussan puutarhaan. Hänen poikansa Joosia tuli kuninkaaksi hänen jälkeensä.',
    },
    22: {
        1: 'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta. Hänen äitinsä oli nimeltään Jedida, Adajan tytär, Boskatista.',
        2: 'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi kaikessa isänsä Daavidin tietä poikkeamatta oikealle tai vasemmalle.',
        3: 'Kahdeksantenatoista hallitusvuotenaan kuningas Joosia lähetti kirjuri Saafanin, Asaljan pojan, Mesullamin pojanpojan, Herran temppeliin ja sanoi:',
        4: '"Mene ylimmäisen papin Hilkian luo, että hän laskisi valmiiksi Herran temppeliin tuodut rahat, joita ovenvartijat ovat koonneet kansalta.',
        5: 'Hän antakoon ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä, ja nämä maksakoot niillä työmiehet, jotka ovat Herran temppelissä korjaamassa sitä, mikä temppelissä on rappeutunutta,',
        6: 'puusepät, rakentajat ja muurarit, sekä temppelin korjaamista varten ostettavat puutavarat ja hakatut kivet.',
        7: 'Älköön heiltä kuitenkaan vaadittako tilintekoa rahoista, jotka heille luovutetaan, vaan toimikoot he luottamusmiehinä."',
        8: 'Ylipappi Hilkia sanoi kirjuri Saafanille: "Löysin lain kirjan Herran temppelistä." Hilkia antoi kirjan Saafanille, ja tämä luki sen.',
        9: 'Kirjuri Saafan meni kuninkaan luo ja teki kuninkaalle selon asiasta sanoen: "Palvelijasi ovat ottaneet esille rahat, mitä temppelissä oli, ja ovat antaneet ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä."',
        10: 'Kirjuri Saafan kertoi kuninkaalle sanoen: "Pappi Hilkia antoi minulle erään kirjan." Sitten Saafan luki sen kuninkaalle.',
        11: 'Kun kuningas kuuli lain kirjan sanat, repäisi hän vaatteensa.',
        12: 'Kuningas käski pappi Hilkiaa, Ahikamia, Saafanin poikaa, Akboria, Miikajan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:',
        13: '"Menkää ja kysykää minun, kansan ja koko Juudan puolesta neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on syttynyt meitä vastaan, koska isämme eivät ole totelleet tämän kirjan sanoja eivätkä tehneet mitään kaikesta siitä, mitä siinä on meille kirjoitettuna."',
        14: 'Pappi Hilkia, Ahikam, Akbor, Saafan ja Asaja menivät naisprofeetta Huldan luo, joka oli vaatevaraston hoitajan Sallumin, Tikvan pojan, Harhaan pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. He puhuivat hänen kanssaan.',
        15: 'Hän sanoi heille: "Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät luokseni:',
        16: "'Näin sanoo Herra: Katso, annan tätä paikkaa ja sen asukkaita kohdata onnettomuuden, kaiken, mitä sanotaan siinä kirjassa, jonka Juudan kuningas on lukenut,",
        17: 'sillä he ovat hylänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla. Minussa on syttynyt viha tätä paikkaa kohtaan eikä sammu.',
        18: 'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka olet kuullut:',
        19: 'Koska sydämesi on pehmennyt ja olet nöyrtynyt Herran edessä kuullessasi, mitä olen puhunut tätä paikkaa ja sen asukkaita vastaan, että he tulevat kauhistukseksi ja kiroussanaksi, ja koska olet reväissyt vaatteesi ja itkenyt edessäni, minäkin olen kuullut sinua, sanoo Herra.',
        20: 'Sen tähden katso, korjaan sinut isiesi luo, ja sinä siirryt rauhassa hautaasi, ja silmäsi pääsevät näkemästä kaikkea sitä onnettomuutta, minkä tuotan tälle paikalle.\'" He toivat kuninkaalle tämän sanan vastauksena.',
    },
    23: {
        1: 'Kuningas lähetti kokoamaan luokseen kaikki Juudan ja Jerusalemin vanhimmat.',
        2: 'Kuningas meni Herran temppeliin, ja hänen kanssaan kaikki Juudan miehet ja kaikki Jerusalemin asukkaat, myös papit ja profeetat, koko kansa pienimmästä suurimpaan. Hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.',
        3: 'Kuningas asettui pylvään viereen ja teki Herran edessä sen liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjään, todistuksiaan ja säädöksiään kaikesta sydämestään ja kaikesta sielustaan ja pitää liiton sanat, jotka olivat kirjoitettuina siinä kirjassa. Kaikki kansa yhtyi siihen liittoon.',
        4: 'Kuningas käski ylimmäistä pappia Hilkiaa ja häntä lähimpiä pappeja sekä ovenvartijoita viemään Herran temppelistä pois kaikki esineet, joita oli tehty Baalille, Aseralle ja kaikelle taivaan joukolle. Hän poltatti ne Jerusalemin ulkopuolella Kidronin kedoilla, mutta vei niiden tuhkan Beeteliin.',
        5: 'Hän pani myös viralta epäjumalien papit, jotka Juudan kuninkaat olivat asettaneet polttamaan uhreja uhrikukkuloilla Juudan kaupungeissa ja Jerusalemin ympäristössä ja jotka polttivat uhreja Baalille, auringolle, kuulle, eläinradan tähdille ja kaikelle taivaan joukolle.',
        6: 'Hän vei aseran pois Herran temppelistä Jerusalemin ulkopuolelle Kidronin laaksoon ja poltti sen Kidronin laaksossa, rouhensi sen tomuksi ja heitti tomun yhteiselle hautausmaalle.',
        7: 'Hän kukisti haureellisten pyhäkköpoikien huoneet, jotka olivat Herran temppelissä ja joissa naiset kutoivat verhoja Aseralle.',
        8: 'Hän toi pois kaikki papit Juudan kaupungeista ja hävitti uhrikukkulat, joilla papit olivat polttaneet uhreja, Gebasta Beersebaan asti. Hän kukisti porteilla olevat uhrikukkulat, joita oli kaupungin päällikön Joosuan portin oven edustalla vasemmalla puolella mentäessä sisään kaupungin portista.',
        9: 'Uhrikukkulapapit eivät kuitenkaan saaneet nousta Herran alttarille Jerusalemissa. He saivat vain syödä happamatonta leipää veljiensä kanssa.',
        10: 'Hän hävitti myös polttopaikan Ben-Hinnomin laaksossa, ettei kukaan voisi panna poikaansa tai tytärtään kulkemaan tulen läpi Molokin kunniaksi.',
        11: 'Hän poisti hevoset, jotka Juudan kuninkaat olivat asettaneet auringon kunniaksi, siitä, mistä mennään Herran temppeliin, hoviherra Netan-Melekin kammion vierestä, joka oli Parvarimissa, ja poltti auringonvaunut tulessa.',
        12: 'Kuningas kukisti Aahaan yläsalin katolla olevat alttarit, jotka Juudan kuninkaat olivat teettäneet, ja ne alttarit, jotka Manasse oli teettänyt Herran temppelin molempiin esipihoihin. Hän riensi sieltä ja heitti niiden tomun Kidronin laaksoon.',
        13: 'Ne uhrikukkulat, jotka olivat itään päin Jerusalemista, etelään päin Turmiovuoresta, ja jotka Salomo, Israelin kuningas, oli rakentanut Astartelle, siidonilaisten iljetykselle, ja Kemokselle, Mooabin iljetykselle, ja Milkomille, ammonilaisten kauhistukselle, ne kuningas hävitti.',
        14: 'Hän murskasi patsaat ja hakkasi maahan aserapaalut ja täytti niiden paikan ihmisten luilla.',
        15: 'Myös Beetelissä olevan alttarin, sen uhrikukkulan, jonka oli teettänyt Jerobeam, Nebatin poika, joka saattoi Israelin tekemään syntiä, senkin alttarin uhrikukkuloineen hän kukisti. Hän poltti uhrikukkulan ja rouhensi sen tomuksi sekä poltti aserapaalun.',
        16: 'Kun Joosia sitten kääntyi ja näki haudat, jotka olivat vuorella, hän lähetti ottamaan luut haudoista, poltti ne alttarilla ja saastutti näin alttarin, Herran sanan mukaan, jonka oli julistanut se Jumalan mies, joka nämä julisti.',
        17: 'Hän kysyi: "Mikä tuo hautamerkki on, jonka minä näen?" Kaupungin miehet vastasivat hänelle: "Se on sen Jumalan miehen hauta, joka tuli Juudasta ja julisti sen, minkä sinä nyt olet tehnyt Beetelin alttarille."',
        18: 'Hän sanoi: "Antakaa hänen olla, älköön kukaan koskeko hänen luihinsa." He jättivät hänen luunsa rauhaan ja samoin sen profeetan luut, joka oli tullut Samariasta.',
        19: 'Myös Samarian kaupungeista Joosia poisti kaikki uhrikukkulatemppelit, jotka Israelin kuninkaat olivat rakentaneet ja niin vihoittaneet Herran, ja hän teki niille saman, minkä oli tehnyt Beetelissä.',
        20: 'Kaikki siellä olevat uhrikukkulapapit hän teurasti alttareilla ja poltti ihmisten luita niiden päällä. Hän palasi takaisin Jerusalemiin.',
        21: 'Kuningas käski kaikkea kansaa sanoen: "Viettäkää pääsiäistä Herran, Jumalanne, kunniaksi, niin kuin on kirjoitettuna tässä liiton kirjassa."',
        22: 'Sillä tätä pääsiäistä ei ollut vietetty sen ajan jälkeen, jona tuomarit tuomitsivat Israelia, ei Israelin kuningasten eikä Juudan kuningasten koko aikana.',
        23: 'Vasta kuningas Joosian kahdeksantenatoista hallitusvuotena vietettiin tämä pääsiäinen Jerusalemissa Herran kunniaksi.',
        24: 'Myös vainaja- ja tietäjähenkien manaajat, kotijumalat ja epäjumalat ja kaikki iljetykset, joita oli nähty Juudan maassa ja Jerusalemissa, Joosia hävitti täyttääkseen lain sanat, jotka olivat kirjoitettuina siinä kirjassa, minkä pappi Hilkia oli löytänyt Herran temppelistä.',
        25: 'Ei ollut ennen häntä ollut hänen vertaistaan kuningasta, joka niin kaikesta sydämestään, kaikesta sielustaan ja kaikesta voimastaan olisi kääntynyt Herran puoleen, kaiken Mooseksen lain mukaan, eikä hänen jälkeensä tullut hänen vertaistaan.',
        26: 'Kuitenkaan Herra ei kääntynyt suuren vihansa hehkusta, kun kerran hänen vihansa oli syttynyt Juudaa vastaan kaikesta siitä, millä Manasse oli vihoittanut hänet.',
        27: 'Herra sanoi: "Juudankin toimitan pois kasvojeni edestä, niin kuin minä olen toimittanut pois Israelin. Hylkään myös Jerusalemin, tämän kaupungin, jonka olin valinnut, ja temppelin, josta olin sanonut: \'Nimeni on siellä oleva.\'"',
        28: 'Se, mitä muuta on kerrottavaa Joosiasta ja kaikesta, mitä hän teki, on kirjoitettuna Juudan kuningasten aikakirjassa.',
        29: 'Hänen aikanaan farao Neko, Egyptin kuningas, lähti Assurin kuningasta vastaan Eufrat-virralle. Kuningas Joosia meni häntä vastaan, mutta farao surmasi hänet Megiddossa heti, kun näki hänet.',
        30: 'Hänen palvelijansa veivät hänet kuolleena vaunuissa Megiddosta, toivat hänet Jerusalemiin ja hautasivat hänet hänen omaan hautaansa. Mutta maan kansa otti Joosian pojan Jooahaan, voiteli hänet ja teki hänet kuninkaaksi hänen isänsä sijaan.',
        31: 'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kolme kuukautta Jerusalemissa. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.',
        32: 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niin kuin hänen isänsä olivat tehneet.',
        33: 'Mutta farao Neko vangitutti hänet Riblassa, Hamatin maassa, ettei hän hallitsisi Jerusalemissa, ja määräsi maan maksettavaksi pakkoveron: sata talenttia hopeaa ja kymmenen talenttia kultaa.',
        34: 'Farao Neko teki Eljakimin, Joosian pojan, kuninkaaksi hänen isänsä Joosian sijaan ja muutti hänen nimensä Joojakimiksi. Mutta Jooahaan hän otti vangiksi, ja tämä joutui Egyptiin. Siellä hän kuoli.',
        35: 'Hopean ja kullan Joojakim maksoi faraolle, mutta voidakseen maksaa rahat faraon käskyn mukaan hän verotti maata ottaen maan kansalta, sen mukaan kuin kutakin oli verotettu, hopeaa ja kultaa antaakseen farao Nekolle.',
        36: 'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Sebida, Pedajan tytär, Ruumasta.',
        37: 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niin kuin hänen isänsä olivat tehneet.',
    },
    24: {
        1: 'Hänen aikanaan Nebukadnessar, Baabelin kuningas, lähti liikkeelle, ja Joojakim tuli hänen palvelijakseen. Kolmen vuoden kuluttua tämä jälleen kapinoi häntä vastaan.',
        2: 'Herra lähetti hänen kimppuunsa kaldealaisten, aramilaisten, mooabilaisten ja ammonilaisten partiojoukkoja. Hän lähetti ne Juudan kimppuun sitä tuhoamaan Herran sanan mukaan, jonka hän oli puhunut palvelijoidensa, profeettojen, kautta.',
        3: 'Mutta tämä tapahtui Juudalle Herran käskystä. Näin hän toimitti heidät pois kasvojensa edestä Manassen syntien tähden, kaiken tähden, mitä hän oli tehnyt,',
        4: 'ja myös viattoman veren tähden, minkä hän oli vuodattanut täyttäessään Jerusalemin viattomalla verellä. Sitä Herra ei halunnut antaa anteeksi.',
        5: 'Se, mitä muuta kerrottavaa on Joojakimista ja kaikesta, mitä hän teki, on kirjoitettuna Juudan kuningasten aikakirjassa.',
        6: 'Joojakim meni lepoon isiensä luo. Hänen poikansa Joojakin tuli kuninkaaksi hänen jälkeensä.',
        7: 'Egyptin kuningas ei enää lähtenyt maastaan, sillä Baabelin kuningas oli vallannut kaiken, mikä oli Egyptin kuninkaan omaa, Egyptin purosta aina Eufrat-virtaan saakka.',
        8: 'Joojakin oli kahdeksantoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kolme kuukautta. Hänen äitinsä oli nimeltään Nehusta, Elnatanin tytär, Jerusalemista.',
        9: 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan kuin hänen isänsä oli tehnyt.',
        10: 'Siihen aikaan Baabelin kuninkaan Nebukadnessarin palvelijat tulivat Jerusalemiin, ja kaupunki saarrettiin.',
        11: 'Nebukadnessar, Baabelin kuningas, ryntäsi kaupunkiin hänen palvelijoidensa saartaessa sitä.',
        12: 'Joojakin, Juudan kuningas, antautui Baabelin kuninkaalle äitineen ja palvelijoineen, päällikköineen ja hoviherroineen. Baabelin kuningas otti hänet vangiksi kahdeksantena hallitusvuotenaan.',
        13: 'Hän vei sieltä pois kaikki Herran temppelin ja kuninkaan linnan aarteet, ja hän rikkoi kaikki kultaesineet, jotka Israelin kuningas Salomo oli teettänyt Herran temppeliin. Tapahtui, niin kuin Herra oli puhunut.',
        14: 'Hän vei karkotukseen koko Jerusalemin, kaikki päälliköt ja kaikki väkevät sankarit, kymmenentuhatta karkotettua, ja kaikki sepät ja lukkosepät. Jäljelle ei jäänyt muita kuin maan köyhiä.',
        15: 'Hän siirsi Joojakinin vankina Baabeliin, samoin hän vei kuninkaan äidin, kuninkaan puolisot ja hänen hoviherransa sekä muut maan mahtavat karkotettuina Jerusalemista Baabeliin,',
        16: 'niin myös kaikki sotilaat luvultaan seitsemäntuhatta, sepät ja lukkosepät luvultaan tuhat, kaikki sotasankareita. Ne Baabelin kuningas vei karkotettuina Baabeliin.',
        17: 'Mutta Baabelin kuningas asetti hänen setänsä Mattanjan kuninkaaksi hänen jälkeensä ja muutti hänen nimensä Sidkiaksi.',
        18: 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.',
        19: 'Sidkia teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.',
        20: 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.',
    },
    25: {
        1: 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, kävi Nebukadnessar, Baabelin kuningas, hän ja koko hänen sotajoukkonsa, Jerusalemin kimppuun ja asettui leiriin sitä vastaan. He rakensivat saartovarusteet sitä vastaan sen ympäri.',
        2: 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.',
        3: 'Mutta neljännen kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä ollut leipää maan kansalle,',
        4: 'valloitettiin kaupunki, ja kaikki sotilaat pakenivat yöllä molempien muurien välistä porttitietä, joka oli kuninkaan puutarhan puolella kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.',
        5: 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat hänet Jerikon aroilla. Koko hänen sotaväkensä oli jättänyt hänet ja hajaantunut.',
        6: 'He ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan. Hänelle julistettiin tuomio:',
        7: 'Sidkian pojat teurastettiin hänen silmiensä edessä, ja Sidkialta itseltään hän sokaisi silmät ja kytki hänet vaskikahleisiin, ja hänet vietiin Baabeliin.',
        8: 'Viidennessä kuussa, kuukauden seitsemäntenä päivänä, Baabelin kuninkaan Nebukadnessarin yhdeksäntenätoista hallitusvuotena, tuli Baabelin kuninkaan palvelija Nebusaradan, henkivartijoiden päällikkö, Jerusalemiin.',
        9: 'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot. Kaikki ylhäisten talot hän poltti tulella.',
        10: 'Koko kaldealaisten sotajoukko, joka henkivartijoiden päälliköllä oli mukanaan, repi maahan Jerusalemin muurit joka puolelta.',
        11: 'Nebusaradan, henkivartijoiden päällikkö, vei karkotukseen kansan tähteet, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja muun rahvaan.',
        12: 'Mutta osan maan köyhiä henkivartioiden päällikkö jätti jäljelle viinitarhureiksi ja peltomiehiksi.',
        13: 'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät vasken Baabeliin.',
        14: 'Kattilat, lapiot, veitset, kupit ja kaikki vaskiesineet, joita oli käytetty jumalanpalveluksessa, he ottivat.',
        15: 'Samoin henkivartijoiden päällikkö otti hiilipannut ja maljat, jotka olivat kokonaan kultaa tai hopeaa.',
        16: 'Molempien pylväiden, meren ja telineiden, jotka Salomo oli teettänyt Herran temppeliin – näiden kaikkien esineiden vaski ei ollut punnittavissa.',
        17: 'Toisen pylvään korkeus oli kahdeksantoista kyynärää. Sen päässä oli pylväänpää vaskesta. Pylväänpään korkeus oli kolme kyynärää. Pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea, ja samanlaiset oli toisessa pylväässä ristikkokoristeen päällä.',
        18: 'Henkivartijoiden päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,',
        19: 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja viisi kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.',
        20: 'Nämä Nebusaradan, henkivartijoiden päällikkö otti ja vei heidät Baabelin kuninkaan eteen Riblaan.',
        21: 'Baabelin kuningas löi heidät kuoliaiksi Riblassa Hamatin maassa. Juuda vietiin pois maastaan karkotukseen.',
        22: 'Mutta sen väen käskynhaltijaksi, joka jäi Juudan maahan, sen, jonka Nebukadnessar, Baabelin kuningas, jätti sinne, hän asetti Gedaljan, Ahikamin pojan, Saafanin pojanpojan.',
        23: 'Kun kaikki sotaväen päälliköt, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan käskynhaltijaksi, he tulivat miehineen Gedaljan luo Mispaan, nimittäin Ismael, Netanjan poika, Joohanan, Kaareahin poika, netofalainen Seraja, Tanhumetin poika, ja Jaasanja, maakatilaisen poika.',
        24: 'Gedalja vannoi heille ja heidän miehilleen ja sanoi heille: "Älkää pelätkö kaldealaisten palvelijoita. Jääkää maahan ja palvelkaa Baabelin kuningasta, niin menestytte."',
        25: 'Mutta seitsemännessä kuussa tuli Ismael, Netanjan poika, Elisaman pojanpoika, joka oli kuninkaallista sukua, mukanaan kymmenen miestä, ja he löivät kuoliaaksi Gedaljan ja ne Juudan miehet ja kaldealaiset, jotka olivat hänen kanssaan Mispassa.',
        26: 'Silloin nousi kaikki kansa, pienimmästä suurimpaan, ja samoin sotaväen päälliköt, ja he menivät Egyptiin, sillä he pelkäsivät kaldealaisia.',
        27: 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety karkotukseen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään vapauttaen hänet vankilasta.',
        28: 'Hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muiden kuninkaiden istuimia, jotka olivat hänen luonaan Baabelissa.',
        29: 'Hän sai panna pois vangin puvun ja aterioida aina hänen luonaan, niin kauan kuin eli.',
        30: 'Hän sai kuninkaalta elatuksensa, mitä kunakin päivänä tarvitsi, vakinaisen elatuksen, niin kauan kuin eli.',
    },
}
